// @FIGURE_CODE_BEGIN
/* ============ constants & axis mapping ============ */
var RED = '#e8423c';
var L10 = function (x) { return Math.log(x) / Math.LN10; };
var PT = 0.006, TT = 0.01, PC = 218, TC = 374;

var TAN = [[-25, 0], [0, 0.18], [0.01, 0.27], [100, 0.645], [374, 0.835], [520, 1]];
var PAN = [[-3, 0], [L10(0.006), 0.345], [0, 0.527], [L10(218), 0.932], [L10(400), 1]];

function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }
function pwmap(A, x) {
  x = cl(x, A[0][0], A[A.length - 1][0]);
  for (var i = 0; i < A.length - 1; i++) {
    if (x <= A[i + 1][0]) {
      var t = (x - A[i][0]) / (A[i + 1][0] - A[i][0]);
      return A[i][1] + t * (A[i + 1][1] - A[i][1]);
    }
  }
  return 1;
}
function pwinv(A, y) {
  y = cl(y, 0, 1);
  for (var i = 0; i < A.length - 1; i++) {
    if (y <= A[i + 1][1]) {
      var t = (y - A[i][1]) / (A[i + 1][1] - A[i][1]);
      return A[i][0] + t * (A[i + 1][0] - A[i][0]);
    }
  }
  return A[A.length - 1][0];
}
function uT(T) { return pwmap(TAN, T); }
function vP(p) { return pwmap(PAN, L10(p)); }
function Tu(u) { return pwinv(TAN, u); }
function Pv(v) { return Math.pow(10, pwinv(PAN, v)); }

/* ============ coexistence curves (physics) ============ */
function pVap(T) { return Math.exp(11.933 - 3975 / (T + 233.15)); }
function tVap(p) { return 3975 / (11.933 - Math.log(p)) - 233.15; }
function pSub(T) { return Math.exp(17.34 - 6135 / (T + 273.15)); }
function tSub(p) { return 6135 / (17.34 - Math.log(p)) - 273.15; }
function tMelt(p) { return TT - (p - PT) / 99.4; }

function phaseOf(T, p) {
  if (p >= PT) {
    if (T <= tMelt(p)) return 'solid';
    if (T >= TC && p >= PC) return 'super';
    if (p >= PC) return 'liquid';
    if (T >= TC) return 'vapor';
    return (p > pVap(T)) ? 'liquid' : 'vapor';
  }
  return (T <= tSub(p)) ? 'solid' : 'vapor';
}
var PHASE = {
  solid: { name: 'Solid (ice)', fill: 'rgba(138,164,200,0.38)', c: '#41618f' },
  liquid: { name: 'Liquid (water)', fill: 'rgba(74,144,217,0.26)', c: '#1a6bbd' },
  vapor: { name: 'Vapor (steam)', fill: 'rgba(242,193,78,0.40)', c: '#a9760a' },
  super: { name: 'Supercritical fluid', fill: 'rgba(163,116,213,0.30)', c: '#7038b0' }
};

var meltPts = [], vapPts = [], subPts = [];
(function buildCurves() {
  var i, p, lp, T;
  for (i = 0; i <= 140; i++) {
    lp = L10(PT) + (L10(400) - L10(PT)) * i / 140; p = Math.pow(10, lp);
    meltPts.push({ x: uT(tMelt(p)), y: vP(p) });
  }
  for (i = 0; i <= 240; i++) {
    T = TT + (TC - TT) * i / 240;
    vapPts.push({ x: uT(T), y: vP(pVap(T)) });
  }
  for (i = 0; i <= 140; i++) {
    lp = -3 + (L10(PT) + 3) * i / 140; p = Math.pow(10, lp);
    subPts.push({ x: uT(tSub(p)), y: vP(p) });
  }
})();

/* ============ state ============ */
var state = { T: 25, p: 1, path: null };
var anim = null, dragging = false;
var gArea = null, gFs = 12, gS = 400;
var scrCurves = { melt: [], vap: [], sub: [] };

var PATHS = {
  'Free explore': null,
  '1 atm path': 1,
  'Low-pressure path (0.003 atm)': 0.003,
  'Supercritical path (250 atm)': 250
};

/* ============ canvas + chart ============ */
var _cv = document.createElement('canvas');
_cv.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(_cv);

function PXu(u) { return gArea.left + u * (gArea.right - gArea.left); }
function PYv(v) { return gArea.bottom - v * (gArea.bottom - gArea.top); }

function txt(ctx, s, x, y, o) {
  o = o || {};
  ctx.save();
  ctx.font = o.font || (gFs + 'px sans-serif');
  ctx.textAlign = o.align || 'left';
  ctx.textBaseline = o.baseline || 'alphabetic';
  if (o.halo !== false) {
    ctx.lineWidth = o.haloW || 3.2; ctx.strokeStyle = '#fff'; ctx.lineJoin = 'round';
    ctx.strokeText(s, x, y);
  }
  ctx.fillStyle = o.color || '#000';
  ctx.fillText(s, x, y);
  ctx.restore();
}
function seg(ctx, x1, y1, x2, y2) { ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke(); }
function head(ctx, x, y, ang, s) {
  ctx.save(); ctx.translate(x, y); ctx.rotate(ang);
  ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-s, s * 0.42); ctx.lineTo(-s, -s * 0.42);
  ctx.closePath(); ctx.fill(); ctx.restore();
}
function curveArrow(ctx, x0, y0, cx, cy, x1, y1, s) {
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.quadraticCurveTo(cx, cy, x1, y1); ctx.stroke();
  head(ctx, x1, y1, Math.atan2(y1 - cy, x1 - cx), s);
}
function fillPoly(ctx, pts, color) {
  if (!pts.length) return;
  ctx.beginPath();
  ctx.moveTo(PXu(pts[0][0]), PYv(pts[0][1]));
  for (var i = 1; i < pts.length; i++) ctx.lineTo(PXu(pts[i][0]), PYv(pts[i][1]));
  ctx.closePath(); ctx.fillStyle = color; ctx.fill();
}
function asArr(a) { return a.map(function (p) { return [p.x, p.y]; }); }
function regionPoly(ph) {
  var u0 = subPts[0].x, uc = uT(TC), vc = vP(PC), um = meltPts[meltPts.length - 1].x;
  if (ph === 'solid') return [[0, 0], [u0, 0]].concat(asArr(subPts)).concat(asArr(meltPts)).concat([[um, 1], [0, 1]]);
  if (ph === 'liquid') return asArr(meltPts).concat([[um, 1], [uc, 1], [uc, vc]]).concat(asArr(vapPts).reverse());
  if (ph === 'vapor') return [[u0, 0]].concat(asArr(subPts)).concat(asArr(vapPts)).concat([[1, vc], [1, 0]]);
  return [[uc, vc], [1, vc], [1, 1], [uc, 1]];
}

function crossings(p) {
  var out = [];
  if (p >= PT) {
    var tm = tMelt(p);
    if (tm > -25 && tm < 520) out.push({ T: tm, label: 'melting' });
    if (p <= PC) { var tb = tVap(p); if (tb < 520) out.push({ T: tb, label: 'boiling' }); }
  } else {
    var ts = tSub(p);
    if (ts > -25 && ts < 520) out.push({ T: ts, label: 'sublimation' });
  }
  return out;
}

/* ---------- background: region wash, path line, dashed guides ---------- */
var bgPlugin = {
  id: 'bgw',
  beforeDatasetsDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea; gArea = a;
    var S = Math.min(chart.width, chart.height); gS = S;
    var ph = phaseOf(state.T, state.p);
    ctx.save();
    ctx.beginPath(); ctx.rect(a.left, a.top, a.right - a.left, a.bottom - a.top); ctx.clip();
    fillPoly(ctx, regionPoly(ph), PHASE[ph].fill);

    /* selected heating path */
    if (state.path) {
      var y = PYv(vP(state.path));
      ctx.setLineDash([6, 4]);
      ctx.strokeStyle = '#444'; ctx.fillStyle = '#444';
      ctx.lineWidth = cl(S * 0.0026, 1, 2);
      seg(ctx, a.left + 2, y, a.right - 10, y);
      ctx.setLineDash([]);
      head(ctx, a.right - 2, y, 0, cl(S * 0.018, 5, 9));
    }

    /* dashed guides */
    ctx.setLineDash([4, 3]);
    ctx.strokeStyle = '#222'; ctx.lineWidth = cl(S * 0.002, 0.8, 1.2);
    var xt = PXu(uT(TT)), yt = PYv(vP(PT));
    seg(ctx, a.left, yt, xt, yt); seg(ctx, xt, yt, xt, a.bottom);
    var xc = PXu(uT(TC)), yc = PYv(vP(PC));
    seg(ctx, a.left, yc, xc, yc); seg(ctx, xc, yc, xc, a.bottom);
    var x1 = PXu(uT(100)), y1 = PYv(vP(1));
    seg(ctx, a.left, y1, x1, y1); seg(ctx, x1, y1, x1, a.bottom);
    ctx.setLineDash([]);
    ctx.restore();
  }
};

/* ---------- foreground: axes, labels, marker ---------- */
var fgPlugin = {
  id: 'fgw',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea; gArea = a;
    var S = Math.min(chart.width, chart.height); gS = S;
    var W = a.right - a.left, H = a.bottom - a.top;
    gFs = cl(S * 0.030, 8, 14);
    var fs = gFs;
    var lw = cl(S * 0.0025, 1, 1.9);
    var tk = cl(S * 0.012, 3, 6);
    var ext = cl(S * 0.038, 10, 20);
    var ah = cl(S * 0.020, 5, 10);

    /* cache screen curves for hit testing */
    function toScr(arr) { return arr.map(function (p) { return [PXu(p.x), PYv(p.y)]; }); }
    scrCurves.melt = toScr(meltPts); scrCurves.vap = toScr(vapPts); scrCurves.sub = toScr(subPts);

    ctx.save();
    ctx.font = fs + 'px sans-serif';
    ctx.lineWidth = lw; ctx.strokeStyle = '#000'; ctx.fillStyle = '#000';

    /* axes with arrowheads */
    seg(ctx, a.left, a.bottom, a.left, a.top - ext + ah);
    head(ctx, a.left, a.top - ext, -Math.PI / 2, ah);
    seg(ctx, a.left, a.bottom, a.right + ext - ah, a.bottom);
    head(ctx, a.right + ext, a.bottom, 0, ah);

    /* ticks */
    var yT = [[218, '218'], [1, '1'], [0.006, '0.006']];
    var maxLW = 0, i;
    for (i = 0; i < yT.length; i++) maxLW = Math.max(maxLW, ctx.measureText(yT[i][1]).width);
    for (i = 0; i < yT.length; i++) {
      var yy = PYv(vP(yT[i][0]));
      ctx.strokeStyle = '#000'; seg(ctx, a.left - tk, yy, a.left, yy);
      txt(ctx, yT[i][1], a.left - tk - 3, yy, { align: 'right', baseline: 'middle', font: fs + 'px sans-serif' });
    }
    var xT = [[0, '0'], [0.01, '0.01'], [100, '100'], [374, '374']];
    for (i = 0; i < xT.length; i++) {
      var xx = PXu(uT(xT[i][0]));
      ctx.strokeStyle = '#000'; seg(ctx, xx, a.bottom, xx, a.bottom + tk);
      txt(ctx, xT[i][1], xx, a.bottom + tk + 2, { align: 'center', baseline: 'top', font: fs + 'px sans-serif' });
    }

    /* axis titles + main title */
    var xTit = Math.max(fs * 0.9, a.left - maxLW - tk - fs * 1.35);
    ctx.save();
    ctx.translate(xTit, (a.top + a.bottom) / 2); ctx.rotate(-Math.PI / 2);
    txt(ctx, 'Pressure, p (atm)', 0, 0, { align: 'center', baseline: 'middle', font: 'bold ' + fs + 'px sans-serif' });
    ctx.restore();
    txt(ctx, 'Temperature, T (°C)', (a.left + a.right) / 2, Math.min(chart.height - 3, a.bottom + tk + fs * 2.6),
      { align: 'center', baseline: 'alphabetic', font: 'bold ' + fs + 'px sans-serif' });
    txt(ctx, 'H₂O', (a.left + a.right) / 2, Math.max(fs * 1.25, a.top - (a.top) * 0.35),
      { align: 'center', baseline: 'alphabetic', font: 'bold ' + (fs * 1.25) + 'px sans-serif' });

    /* region letters */
    var rf = 'italic ' + (fs * 1.3) + 'px Georgia, serif';
    txt(ctx, 's', PXu(0.113), PYv(0.41), { align: 'center', baseline: 'middle', font: rf });
    txt(ctx, 'l', PXu(0.40), PYv(0.70), { align: 'center', baseline: 'middle', font: rf });
    txt(ctx, 'v', PXu(0.72), PYv(0.36), { align: 'center', baseline: 'middle', font: rf });

    /* triple + critical point dots */
    var rdot = cl(S * 0.0115, 3, 6);
    var xt = PXu(uT(TT)), yt = PYv(vP(PT));
    var xc = PXu(uT(TC)), yc = PYv(vP(PC));
    ctx.fillStyle = '#000';
    ctx.beginPath(); ctx.arc(xt, yt, rdot, 0, 6.2832); ctx.fill();
    ctx.beginPath(); ctx.arc(xc, yc, rdot, 0, 6.2832); ctx.fill();
    txt(ctx, 'Triple', xt + rdot + 4, yt + fs * 0.95, { font: fs + 'px sans-serif' });
    txt(ctx, 'point', xt + rdot + 4, yt + fs * 2.05, { font: fs + 'px sans-serif' });
    var cpw = ctx.measureText('Critical point').width;
    var cpx = cl(xc - cpw * 0.45, 3, chart.width - cpw - 3);
    txt(ctx, 'Critical point', cpx, yc - rdot - fs * 0.55, { font: fs + 'px sans-serif' });

    /* outside annotations */
    var af = fs * 0.95;
    ctx.font = af + 'px sans-serif';
    while (af > 7 && ctx.measureText('Sublimation').width > a.left - 6) { af -= 0.5; ctx.font = af + 'px sans-serif'; }
    var annF = af + 'px sans-serif';
    ctx.lineWidth = cl(S * 0.0022, 0.9, 1.6); ctx.strokeStyle = '#000'; ctx.fillStyle = '#000';
    var hs = cl(S * 0.016, 4, 8);

    // Melting (upper left)
    var mTargetY = PYv(0.72), mTargetX = PXu(0.179);
    var mtw = ctx.measureText('Melting').width;
    var mx = Math.max(mtw + 3, a.left - maxLW - tk - 8);
    txt(ctx, 'Melting', mx, PYv(0.845), { align: 'right', baseline: 'middle', font: annF });
    curveArrow(ctx, mx + 5, PYv(0.845), (mx + mTargetX) / 2, PYv(0.80), mTargetX - 6, mTargetY, hs);

    // Sublimation (lower left)
    var stw = ctx.measureText('Sublimation').width;
    var sx = Math.max(stw + 3, a.left - 6);
