    var sTx = PXu(0.0835), sTy = PYv(0.118);
    curveArrow(ctx, sx + 5, PYv(0.045), (sx + sTx) / 2 + 6, PYv(0.035), sTx - 3, sTy + 4, hs);

    // Boiling (right)
    var btw = ctx.measureText('Boiling').width;
    var bx = Math.min(a.right + 8, chart.width - btw - 3);
    txt(ctx, 'Boiling', bx, PYv(0.545), { align: 'left', baseline: 'middle', font: annF });
    var bTx = PXu(0.700), bTy = PYv(0.700);
    curveArrow(ctx, bx - 4, PYv(0.545), (bx + bTx) / 2, PYv(0.545), bTx + 6, bTy, hs);

