      var yp = PYv(vP(state.path));
      var cs = crossings(state.path);
      ctx.strokeStyle = '#333';
      for (i = 0; i < cs.length; i++) {
        var cxp = PXu(uT(cs[i].T));
        if (cxp < a.left || cxp > a.right) continue;
        ctx.lineWidth = cl(S * 0.0026, 1, 2);
        seg(ctx, cxp, yp - hs, cxp, yp + hs);
        var done = state.T >= cs[i].T;
        txt(ctx, cs[i].label, cxp, yp - hs - 3,
          { align: 'center', baseline: 'alphabetic', font: (done ? 'bold ' : '') + (fs * 0.82) + 'px sans-serif', color: done ? '#b0300a' : '#444' });
      }
      if (state.path > PC) {
        txt(ctx, 'no liquid–vapor boundary', PXu(0.66), yp + hs + fs * 1.0,
          { align: 'center', baseline: 'alphabetic', font: (fs * 0.82) + 'px sans-serif', color: '#7038b0' });
      }
    }

    /* state marker + readout */
    var ph = phaseOf(state.T, state.p);
    var mxp = PXu(uT(cl(state.T, -25, 520))), myp = PYv(vP(cl(state.p, 0.001, 400)));
    var rm = cl(S * 0.017, 4.5, 9);
    ctx.save();
    ctx.lineWidth = cl(S * 0.0045, 1.5, 3);
    ctx.fillStyle = '#fff'; ctx.strokeStyle = '#111';
    ctx.beginPath(); ctx.arc(mxp, myp, rm, 0, 6.2832); ctx.fill(); ctx.stroke();
    ctx.fillStyle = PHASE[ph].c;
    ctx.beginPath(); ctx.arc(mxp, myp, rm * 0.34, 0, 6.2832); ctx.fill();
    ctx.restore();

    var l1 = 'T = ' + fmtT(state.T) + ' °C   p = ' + fmtP(state.p) + ' atm';
    var l2 = PHASE[ph].name;
    var bf = cl(fs * 0.88, 8, 12);
    ctx.font = bf + 'px sans-serif';
    var bw = Math.max(ctx.measureText(l1).width, ctx.measureText(l2).width) + 10;
    var bh = bf * 2.7 + 6;
    var bxp = mxp + rm + 8, byp = myp - bh - rm - 4;
    if (bxp + bw > a.right - 2) bxp = mxp - rm - 8 - bw;
    if (byp < a.top + 2) byp = myp + rm + 6;
    bxp = cl(bxp, a.left + 2, a.right - bw - 2);
    byp = cl(byp, a.top + 2, a.bottom - bh - 2);
    ctx.save();
    ctx.fillStyle = 'rgba(255,255,255,0.92)'; ctx.strokeStyle = '#555'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.rect(bxp, byp, bw, bh); ctx.fill(); ctx.stroke();
    ctx.restore();
    txt(ctx, l1, bxp + 5, byp + bf * 1.15, { font: bf + 'px sans-serif', halo: false });
    txt(ctx, l2, bxp + 5, byp + bf * 2.35, { font: 'bold ' + bf + 'px sans-serif', color: PHASE[ph].c, halo: false });

    ctx.restore();
  }
};

