/* ============ formatting + state setters ============ */
function fmtT(T) { return (Math.abs(T) < 1 && T !== 0) ? T.toFixed(2) : (Math.abs(T) < 10 ? T.toFixed(1) : T.toFixed(0)); }
function fmtP(p) {
  if (p < 0.01) return p.toFixed(4);
  if (p < 1) return p.toFixed(3);
  if (p < 10) return p.toFixed(2);
  return p.toFixed(0);
}
function setT(T) {
  state.T = T;
  var i = document.getElementById('temperatureInput');
  i.value = String(T);
  document.getElementById('temperatureVal').value = fmtT(T);
}
function setP(p) {
  state.p = p;
  var i = document.getElementById('pressureInput');
  i.value = String(cl(L10(p), -3, 2.477));
  document.getElementById('pressureVal').value = fmtP(p);
}
function redraw() {
  var ph = phaseOf(state.T, state.p);
  var el = document.getElementById('phaseReadout');
  el.textContent = 'Phase: ' + PHASE[ph].name;
  el.style.color = PHASE[ph].c;
  chart.update('none');
}
function stopAnim() { if (anim) { cancelAnimationFrame(anim); anim = null; } }

/* ============ control handlers ============ */
function update_temperature(v) { stopAnim(); state.T = v; redraw(); }
function update_pressure(lg) {
  stopAnim();
  var p = cl(Math.pow(10, lg), 0.001, 300);
  state.p = p;
  document.getElementById('pressureVal').value = fmtP(p);
  redraw();
}
function applyPath(name) {
  state.path = PATHS[name] || null;
  var pi = document.getElementById('pressureInput');
  if (state.path) { setP(state.path); pi.disabled = true; } else { pi.disabled = false; }
}
function toggle_heatingPath(v) { stopAnim(); applyPath(v); redraw(); }
function pathEndT() {
  var p = state.p;
  if (p > PC) return 480;
  if (p < PT) return 180;
  return cl(tVap(p) + 90, 130, 480);
}
function animateTo(target) {
  stopAnim();
  var from = state.T, t0 = performance.now(), dur = 3500;
  function frame(now) {
    var k = cl((now - t0) / dur, 0, 1);
    setT(Math.round((from + (target - from) * k) * 100) / 100);
    redraw();
    anim = (k < 1) ? requestAnimationFrame(frame) : null;
  }
  anim = requestAnimationFrame(frame);
}
function trigger_tracePath() { stopAnim(); var end = pathEndT(); setT(-20); redraw(); animateTo(end); }

/* ============ demo steps ============ */
var STEPS = [
  { title: 'Read the map', narration: 'Three red curves carve the plane into solid (s), liquid (l) and vapor (v). The state point sits at room conditions, 25 °C and 1 atm, inside the liquid wedge — water is liquid there for no other reason than its location on this map.', state: { temperature: 25, pressure: 1, heatingPath: 'Free explore' } },
  { title: 'Cross the boiling curve', narration: 'Slide the temperature right at 1 atm. At 100 °C the point crosses the vaporization curve and the highlighted region flips from liquid to vapor — that crossing is boiling.', state: { temperature: 130, pressure: 1, heatingPath: 'Free explore' } },
  { title: 'The triple point', narration: 'Drop the pressure to 0.006 atm and the temperature to 0.01 °C. All three curves meet at this single dot, the one condition where ice, water and steam coexist.', state: { temperature: 0.01, pressure: 0.006, heatingPath: 'Free explore' } },
  { title: 'Squeeze ice into water', narration: 'Park the temperature just below 0 °C in the solid region and raise the pressure. Because water\u2019s melting curve leans LEFT, climbing vertically eventually crosses it and the label changes from solid to liquid — pressure alone melts ice.', state: { temperature: -2, pressure: 200, heatingPath: 'Free explore' } },
  { title: 'Sublimation path', narration: 'Choose the low-pressure path, below the triple-point pressure, and heat. The point crosses only the sublimation curve: ice turns straight into vapor with no liquid stage.', state: { heatingPath: 'Low-pressure path (0.003 atm)', pressure: 0.003, temperature: 20 } },
  { title: 'Past the critical point', narration: 'Now take the supercritical path above 218 atm and heat past 374 °C. Beyond the critical point no liquid–vapor boundary exists — liquid and vapor merge continuously into one indistinguishable supercritical fluid.', state: { heatingPath: 'Supercritical path (250 atm)', pressure: 250, temperature: 450 } }
];
var curStep = 0;
function applyStep(i) {
  stopAnim();
  curStep = (i + STEPS.length) % STEPS.length;
  var s = STEPS[curStep], st = s.state;
  if (st.heatingPath !== undefined) {
    document.getElementById('heatingPathInput').value = st.heatingPath;
    applyPath(st.heatingPath);
  }
  if (st.pressure !== undefined) setP(st.pressure);
  if (st.temperature !== undefined) setT(st.temperature);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + STEPS.length + ' · ' + s.title;
  redraw();
  if (st.heatingPath && st.heatingPath !== 'Free explore') {
    setT(-20); redraw();
    setTimeout(function () { animateTo(st.temperature); }, 350);
