/* ============ constants & axis mapping ============ */
var RED = '#e8423c';
var L10 = function (x) { return Math.log(x) / Math.LN10; };
var PT = 0.006, TT = 0.01, PC = 218, TC = 374;

var TAN = [[-25, 0], [0, 0.18], [0.01, 0.27], [100, 0.645], [374, 0.835], [520, 1]];
var PAN = [[-3, 0], [L10(0.006), 0.345], [0, 0.527], [L10(218), 0.932], [L10(400), 1]];

function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }
function pwmap(A, x) {
  x = cl(x, A[0][0], A[A.length - 1][0]);
  for (var i = 0; i < A.length - 1; i++) {
    if (x <= A[i + 1][0]) {
      var t = (x - A[i][0]) / (A[i + 1][0] - A[i][0]);
      return A[i][1] + t * (A[i + 1][1] - A[i][1]);
    }
  }
  return 1;
}
function pwinv(A, y) {
  y = cl(y, 0, 1);
  for (var i = 0; i < A.length - 1; i++) {
    if (y <= A[i + 1][1]) {
      var t = (y - A[i][1]) / (A[i + 1][1] - A[i][1]);
      return A[i][0] + t * (A[i + 1][0] - A[i][0]);
    }
  }
  return A[A.length - 1][0];
}
function uT(T) { return pwmap(TAN, T); }
function vP(p) { return pwmap(PAN, L10(p)); }
function Tu(u) { return pwinv(TAN, u); }
function Pv(v) { return Math.pow(10, pwinv(PAN, v)); }

/* ============ coexistence curves (physics) ============ */
function pVap(T) { return Math.exp(11.933 - 3975 / (T + 233.15)); }
function tVap(p) { return 3975 / (11.933 - Math.log(p)) - 233.15; }
function pSub(T) { return Math.exp(17.34 - 6135 / (T + 273.15)); }
function tSub(p) { return 6135 / (17.34 - Math.log(p)) - 273.15; }
function tMelt(p) { return TT - (p - PT) / 99.4; }

function phaseOf(T, p) {
  if (p >= PT) {
    if (T <= tMelt(p)) return 'solid';
    if (T >= TC && p >= PC) return 'super';
    if (p >= PC) return 'liquid';
    if (T >= TC) return 'vapor';
    return (p > pVap(T)) ? 'liquid' : 'vapor';
  }
  return (T <= tSub(p)) ? 'solid' : 'vapor';
}
