    var xt = PXu(uT(TT)), yt = PYv(vP(PT));
    seg(ctx, a.left, yt, xt, yt); seg(ctx, xt, yt, xt, a.bottom);
    var xc = PXu(uT(TC)), yc = PYv(vP(PC));
    seg(ctx, a.left, yc, xc, yc); seg(ctx, xc, yc, xc, a.bottom);
    var x1 = PXu(uT(100)), y1 = PYv(vP(1));
    seg(ctx, a.left, y1, x1, y1); seg(ctx, x1, y1, x1, a.bottom);
    ctx.setLineDash([]);
    ctx.restore();
  }
};

/* ---------- foreground: axes, labels, marker ---------- */
var fgPlugin = {
  id: 'fgw',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea; gArea = a;
    var S = Math.min(chart.width, chart.height); gS = S;
    var W = a.right - a.left, H = a.bottom - a.top;
    gFs = cl(S * 0.030, 8, 14);
    var fs = gFs;
    var lw = cl(S * 0.0025, 1, 1.9);
    var tk = cl(S * 0.012, 3, 6);
    var ext = cl(S * 0.038, 10, 20);
    var ah = cl(S * 0.020, 5, 10);

    /* cache screen curves for hit testing */
    function toScr(arr) { return arr.map(function (p) { return [PXu(p.x), PYv(p.y)]; }); }
    scrCurves.melt = toScr(meltPts); scrCurves.vap = toScr(vapPts); scrCurves.sub = toScr(subPts);

    ctx.save();
    ctx.font = fs + 'px sans-serif';
    ctx.lineWidth = lw; ctx.strokeStyle = '#000'; ctx.fillStyle = '#000';

    /* axes with arrowheads */
    seg(ctx, a.left, a.bottom, a.left, a.top - ext + ah);
    head(ctx, a.left, a.top - ext, -Math.PI / 2, ah);
    seg(ctx, a.left, a.bottom, a.right + ext - ah, a.bottom);
    head(ctx, a.right + ext, a.bottom, 0, ah);

    /* ticks */
    var yT = [[218, '218'], [1, '1'], [0.006, '0.006']];
    var maxLW = 0, i;
    for (i = 0; i < yT.length; i++) maxLW = Math.max(maxLW, ctx.measureText(yT[i][1]).width);
    for (i = 0; i < yT.length; i++) {
      var yy = PYv(vP(yT[i][0]));
      ctx.strokeStyle = '#000'; seg(ctx, a.left - tk, yy, a.left, yy);
      txt(ctx, yT[i][1], a.left - tk - 3, yy, { align: 'right', baseline: 'middle', font: fs + 'px sans-serif' });
    }
    var xT = [[0, '0'], [0.01, '0.01'], [100, '100'], [374, '374']];
    for (i = 0; i < xT.length; i++) {
      var xx = PXu(uT(xT[i][0]));
      ctx.strokeStyle = '#000'; seg(ctx, xx, a.bottom, xx, a.bottom + tk);
      txt(ctx, xT[i][1], xx, a.bottom + tk + 2, { align: 'center', baseline: 'top', font: fs + 'px sans-serif' });
    }

    /* axis titles + main title */
    var xTit = Math.max(fs * 0.9, a.left - maxLW - tk - fs * 1.35);
    ctx.save();
    ctx.translate(xTit, (a.top + a.bottom) / 2); ctx.rotate(-Math.PI / 2);
    txt(ctx, 'Pressure, p (atm)', 0, 0, { align: 'center', baseline: 'middle', font: 'bold ' + fs + 'px sans-serif' });
    ctx.restore();
    txt(ctx, 'Temperature, T (°C)', (a.left + a.right) / 2, Math.min(chart.height - 3, a.bottom + tk + fs * 2.6),
      { align: 'center', baseline: 'alphabetic', font: 'bold ' + fs + 'px sans-serif' });
    txt(ctx, 'H₂O', (a.left + a.right) / 2, Math.max(fs * 1.25, a.top - (a.top) * 0.35),
      { align: 'center', baseline: 'alphabetic', font: 'bold ' + (fs * 1.25) + 'px sans-serif' });

    /* region letters */
    var rf = 'italic ' + (fs * 1.3) + 'px Georgia, serif';
    txt(ctx, 's', PXu(0.113), PYv(0.41), { align: 'center', baseline: 'middle', font: rf });
    txt(ctx, 'l', PXu(0.40), PYv(0.70), { align: 'center', baseline: 'middle', font: rf });
    txt(ctx, 'v', PXu(0.72), PYv(0.36), { align: 'center', baseline: 'middle', font: rf });

    /* triple + critical point dots */
    var rdot = cl(S * 0.0115, 3, 6);
    var xt = PXu(uT(TT)), yt = PYv(vP(PT));
    var xc = PXu(uT(TC)), yc = PYv(vP(PC));
    ctx.fillStyle = '#000';
    ctx.beginPath(); ctx.arc(xt, yt, rdot, 0, 6.2832); ctx.fill();
    ctx.beginPath(); ctx.arc(xc, yc, rdot, 0, 6.2832); ctx.fill();
    txt(ctx, 'Triple', xt + rdot + 4, yt + fs * 0.95, { font: fs + 'px sans-serif' });
    txt(ctx, 'point', xt + rdot + 4, yt + fs * 2.05, { font: fs + 'px sans-serif' });
    var cpw = ctx.measureText('Critical point').width;
    var cpx = cl(xc - cpw * 0.45, 3, chart.width - cpw - 3);
    txt(ctx, 'Critical point', cpx, yc - rdot - fs * 0.55, { font: fs + 'px sans-serif' });

    /* outside annotations */
    var af = fs * 0.95;
    ctx.font = af + 'px sans-serif';
    while (af > 7 && ctx.measureText('Sublimation').width > a.left - 6) { af -= 0.5; ctx.font = af + 'px sans-serif'; }
    var annF = af + 'px sans-serif';
    ctx.lineWidth = cl(S * 0.0022, 0.9, 1.6); ctx.strokeStyle = '#000'; ctx.fillStyle = '#000';
    var hs = cl(S * 0.016, 4, 8);

    // Melting (upper left)
    var mTargetY = PYv(0.72), mTargetX = PXu(0.179);
    var mtw = ctx.measureText('Melting').width;
    var mx = Math.max(mtw + 3, a.left - maxLW - tk - 8);
    txt(ctx, 'Melting', mx, PYv(0.845), { align: 'right', baseline: 'middle', font: annF });
    curveArrow(ctx, mx + 5, PYv(0.845), (mx + mTargetX) / 2, PYv(0.80), mTargetX - 6, mTargetY, hs);

    // Sublimation (lower left)
    var stw = ctx.measureText('Sublimation').width;
    var sx = Math.max(stw + 3, a.left - 6);
    txt(ctx, 'Sublimation', sx, PYv(0.045), { align: 'right', baseline: 'middle', font: annF });
    var sTx = PXu(0.0835), sTy = PYv(0.118);
    curveArrow(ctx, sx + 5, PYv(0.045), (sx + sTx) / 2 + 6, PYv(0.035), sTx - 3, sTy + 4, hs);

    // Boiling (right)
    var btw = ctx.measureText('Boiling').width;
    var bx = Math.min(a.right + 8, chart.width - btw - 3);
    txt(ctx, 'Boiling', bx, PYv(0.545), { align: 'left', baseline: 'middle', font: annF });
    var bTx = PXu(0.700), bTy = PYv(0.700);
    curveArrow(ctx, bx - 4, PYv(0.545), (bx + bTx) / 2, PYv(0.545), bTx + 6, bTy, hs);

    /* path crossings */
    if (state.path) {
      var yp = PYv(vP(state.path));
      var cs = crossings(state.path);
      ctx.strokeStyle = '#333';
      for (i = 0; i < cs.length; i++) {
        var cxp = PXu(uT(cs[i].T));
        if (cxp < a.left || cxp > a.right) continue;
        ctx.lineWidth = cl(S * 0.0026, 1, 2);
        seg(ctx, cxp, yp - hs, cxp, yp + hs);
        var done = state.T >= cs[i].T;
        txt(ctx, cs[i].label, cxp, yp - hs - 3,
          { align: 'center', baseline: 'alphabetic', font: (done ? 'bold ' : '') + (fs * 0.82) + 'px sans-serif', color: done ? '#b0300a' : '#444' });
      }
      if (state.path > PC) {
        txt(ctx, 'no liquid–vapor boundary', PXu(0.66), yp + hs + fs * 1.0,
          { align: 'center', baseline: 'alphabetic', font: (fs * 0.82) + 'px sans-serif', color: '#7038b0' });
      }
    }

    /* state marker + readout */
    var ph = phaseOf(state.T, state.p);
    var mxp = PXu(uT(cl(state.T, -25, 520))), myp = PYv(vP(cl(state.p, 0.001, 400)));
    var rm = cl(S * 0.017, 4.5, 9);
    ctx.save();
    ctx.lineWidth = cl(S * 0.0045, 1.5, 3);
    ctx.fillStyle = '#fff'; ctx.strokeStyle = '#111';
    ctx.beginPath(); ctx.arc(mxp, myp, rm, 0, 6.2832); ctx.fill(); ctx.stroke();
    ctx.fillStyle = PHASE[ph].c;
    ctx.beginPath(); ctx.arc(mxp, myp, rm * 0.34, 0, 6.2832); ctx.fill();
    ctx.restore();

    var l1 = 'T = ' + fmtT(state.T) + ' °C   p = ' + fmtP(state.p) + ' atm';
    var l2 = PHASE[ph].name;
    var bf = cl(fs * 0.88, 8, 12);
    ctx.font = bf + 'px sans-serif';
    var bw = Math.max(ctx.measureText(l1).width, ctx.measureText(l2).width) + 10;
    var bh = bf * 2.7 + 6;
    var bxp = mxp + rm + 8, byp = myp - bh - rm - 4;
    if (bxp + bw > a.right - 2) bxp = mxp - rm - 8 - bw;
    if (byp < a.top + 2) byp = myp + rm + 6;
    bxp = cl(bxp, a.left + 2, a.right - bw - 2);
    byp = cl(byp, a.top + 2, a.bottom - bh - 2);
    ctx.save();
    ctx.fillStyle = 'rgba(255,255,255,0.92)'; ctx.strokeStyle = '#555'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.rect(bxp, byp, bw, bh); ctx.fill(); ctx.stroke();
    ctx.restore();
    txt(ctx, l1, bxp + 5, byp + bf * 1.15, { font: bf + 'px sans-serif', halo: false });
    txt(ctx, l2, bxp + 5, byp + bf * 2.35, { font: 'bold ' + bf + 'px sans-serif', color: PHASE[ph].c, halo: false });

    ctx.restore();
  }
};

var layoutPlugin = {
  id: 'padw',
  beforeLayout: function (chart) {
    var w = chart.width, h = chart.height;
    var S = Math.min(w, h);
    chart.options.layout.padding = {
      left: cl(w * 0.20, 54, 130),
      right: cl(w * 0.15, 46, 105),
      top: cl(h * 0.14, 34, 74),
      bottom: cl(h * 0.15, 38, 76)
    };
    var bw = cl(S * 0.0048, 1.5, 2.6);
    chart.data.datasets.forEach(function (d) { d.borderWidth = bw; });
  }
};

var chart = new Chart(_cv.getContext('2d'), {
  type: 'scatter',
  data: {
    datasets: [
      { label: 'melting', data: meltPts, showLine: true, pointRadius: 0, borderColor: RED, borderWidth: 2, tension: 0 },
      { label: 'vaporization', data: vapPts, showLine: true, pointRadius: 0, borderColor: RED, borderWidth: 2, tension: 0 },
      { label: 'sublimation', data: subPts, showLine: true, pointRadius: 0, borderColor: RED, borderWidth: 2, tension: 0 }
    ]
  },
  options: {
    responsive: true, maintainAspectRatio: false, animation: false, events: [],
    layout: { padding: 40 },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: { type: 'linear', min: 0, max: 1, display: false },
      y: { type: 'linear', min: 0, max: 1, display: false }
    }
  },
  plugins: [layoutPlugin, bgPlugin, fgPlugin]
});
window.__markRendered();

/* ============ formatting + state setters ============ */
function fmtT(T) { return (Math.abs(T) < 1 && T !== 0) ? T.toFixed(2) : (Math.abs(T) < 10 ? T.toFixed(1) : T.toFixed(0)); }
function fmtP(p) {
  if (p < 0.01) return p.toFixed(4);
  if (p < 1) return p.toFixed(3);
  if (p < 10) return p.toFixed(2);
  return p.toFixed(0);
}
function setT(T) {
  state.T = T;
  var i = document.getElementById('temperatureInput');
  i.value = String(T);
  document.getElementById('temperatureVal').value = fmtT(T);
}
function setP(p) {
  state.p = p;
  var i = document.getElementById('pressureInput');
  i.value = String(cl(L10(p), -3, 2.477));
  document.getElementById('pressureVal').value = fmtP(p);
}
function redraw() {
  var ph = phaseOf(state.T, state.p);
  var el = document.getElementById('phaseReadout');
  el.textContent = 'Phase: ' + PHASE[ph].name;
  el.style.color = PHASE[ph].c;
  chart.update('none');
}
function stopAnim() { if (anim) { cancelAnimationFrame(anim); anim = null; } }

/* ============ control handlers ============ */
function update_temperature(v) { stopAnim(); state.T = v; redraw(); }
function update_pressure(lg) {
  stopAnim();
  var p = cl(Math.pow(10, lg), 0.001, 300);
  state.p = p;
  document.getElementById('pressureVal').value = fmtP(p);
  redraw();
}
function applyPath(name) {
  state.path = PATHS[name] || null;
  var pi = document.getElementById('pressureInput');
  if (state.path) { setP(state.path); pi.disabled = true; } else { pi.disabled = false; }
}
function toggle_heatingPath(v) { stopAnim(); applyPath(v); redraw(); }
function pathEndT() {
  var p = state.p;
  if (p > PC) return 480;
  if (p < PT) return 180;
  return cl(tVap(p) + 90, 130, 480);
}
function animateTo(target) {
  stopAnim();
  var from = state.T, t0 = performance.now(), dur = 3500;
  function frame(now) {
    var k = cl((now - t0) / dur, 0, 1);
    setT(Math.round((from + (target - from) * k) * 100) / 100);
    redraw();
    anim = (k < 1) ? requestAnimationFrame(frame) : null;
  }
  anim = requestAnimationFrame(frame);
}
function trigger_tracePath() { stopAnim(); var end = pathEndT(); setT(-20); redraw(); animateTo(end); }

/* ============ demo steps ============ */
var STEPS = [
  { title: 'Read the map', narration: 'Three red curves carve the plane into solid (s), liquid (l) and vapor (v). The state point sits at room conditions, 25 °C and 1 atm, inside the liquid wedge — water is liquid there for no other reason than its location on this map.', state: { temperature: 25, pressure: 1, heatingPath: 'Free explore' } },
  { title: 'Cross the boiling curve', narration: 'Slide the temperature right at 1 atm. At 100 °C the point crosses the vaporization curve and the highlighted region flips from liquid to vapor — that crossing is boiling.', state: { temperature: 130, pressure: 1, heatingPath: 'Free explore' } },
  { title: 'The triple point', narration: 'Drop the pressure to 0.006 atm and the temperature to 0.01 °C. All three curves meet at this single dot, the one condition where ice, water and steam coexist.', state: { temperature: 0.01, pressure: 0.006, heatingPath: 'Free explore' } },
  { title: 'Squeeze ice into water', narration: 'Park the temperature just below 0 °C in the solid region and raise the pressure. Because water\u2019s melting curve leans LEFT, climbing vertically eventually crosses it and the label changes from solid to liquid — pressure alone melts ice.', state: { temperature: -2, pressure: 200, heatingPath: 'Free explore' } },
  { title: 'Sublimation path', narration: 'Choose the low-pressure path, below the triple-point pressure, and heat. The point crosses only the sublimation curve: ice turns straight into vapor with no liquid stage.', state: { heatingPath: 'Low-pressure path (0.003 atm)', pressure: 0.003, temperature: 20 } },
  { title: 'Past the critical point', narration: 'Now take the supercritical path above 218 atm and heat past 374 °C. Beyond the critical point no liquid–vapor boundary exists — liquid and vapor merge continuously into one indistinguishable supercritical fluid.', state: { heatingPath: 'Supercritical path (250 atm)', pressure: 250, temperature: 450 } }
];
var curStep = 0;
function applyStep(i) {
  stopAnim();
  curStep = (i + STEPS.length) % STEPS.length;
  var s = STEPS[curStep], st = s.state;
  if (st.heatingPath !== undefined) {
    document.getElementById('heatingPathInput').value = st.heatingPath;
    applyPath(st.heatingPath);
  }
  if (st.pressure !== undefined) setP(st.pressure);
  if (st.temperature !== undefined) setT(st.temperature);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + STEPS.length + ' · ' + s.title;
  redraw();
  if (st.heatingPath && st.heatingPath !== 'Free explore') {
    setT(-20); redraw();
    setTimeout(function () { animateTo(st.temperature); }, 350);
  }
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

/* ============ hover / click / drag ============ */
function dist2seg(px, py, x1, y1, x2, y2) {
  var dx = x2 - x1, dy = y2 - y1, L = dx * dx + dy * dy;
  var t = L ? cl(((px - x1) * dx + (py - y1) * dy) / L, 0, 1) : 0;
  var ax = x1 + t * dx - px, ay = y1 + t * dy - py;
  return Math.sqrt(ax * ax + ay * ay);
}
function nearCurve(pts, x, y) {
  var m = 1e9;
  for (var i = 1; i < pts.length; i++) m = Math.min(m, dist2seg(x, y, pts[i - 1][0], pts[i - 1][1], pts[i][0], pts[i][1]));
  return m;
}
function inArea(x, y) { return gArea && x >= gArea.left && x <= gArea.right && y >= gArea.top && y <= gArea.bottom; }
function hitTest(x, y) {
  if (!gArea) return null;
  var r = cl(gS * 0.03, 8, 14);
  var xt = PXu(uT(TT)), yt = PYv(vP(PT)), xc = PXu(uT(TC)), yc = PYv(vP(PC));
  if (Math.hypot(x - xt, y - yt) < r) return {
    tip: 'Triple point — 0.01 °C, 0.006 atm', title: 'Triple point',
    popup: 'At 0.01 °C and 0.006 atm the melting, boiling and sublimation curves all meet. This is the only pressure–temperature combination where ice, liquid water and water vapor coexist in equilibrium.'
  };
  if (Math.hypot(x - xc, y - yc) < r) return {
    tip: 'Critical point — 374 °C, 218 atm', title: 'Critical point',
    popup: 'The vaporization curve ends here at 374 °C and 218 atm. Above the critical point the liquid and vapor densities become equal, so there is no boundary left to cross: the substance is a single supercritical fluid.'
  };
  var th = cl(gS * 0.018, 5, 9);
  if (nearCurve(scrCurves.melt, x, y) < th) return {
    tip: 'Fusion (melting) curve — solid ⇄ liquid', title: 'Melting (fusion) curve',
    popup: 'This boundary separates ice from liquid water. For water it leans to the LEFT (negative slope) because ice is less dense than liquid, so squeezing ice at constant temperature can push it across the curve and melt it.'
  };
  if (nearCurve(scrCurves.vap, x, y) < th) return {
    tip: 'Vaporization (boiling) curve — liquid ⇄ vapor', title: 'Vaporization curve',
    popup: 'Along this curve liquid and vapor coexist; it gives the boiling temperature at each pressure (100 °C at 1 atm). It starts at the triple point and terminates at the critical point, where the distinction between liquid and vapor disappears.'
  };
  if (nearCurve(scrCurves.sub, x, y) < th) return {
    tip: 'Sublimation curve — solid ⇄ vapor', title: 'Sublimation curve',
    popup: 'Below the triple-point pressure of 0.006 atm no liquid can exist. Heating ice at such low pressure carries the state point across this curve, and the solid passes directly into vapor — sublimation.'
  };
  return null;
}
function setFromPos(x, y) {
  var u = cl((x - gArea.left) / (gArea.right - gArea.left), 0, 1);
  var v = cl((gArea.bottom - y) / (gArea.bottom - gArea.top), 0, 1);
  var T = Tu(u);
  T = (Math.abs(T) < 2) ? Math.round(T * 100) / 100 : Math.round(T * 10) / 10;
  setT(cl(T, -20, 500));
  if (!state.path) setP(cl(Pv(v), 0.001, 300));
  redraw();
}
_cv.addEventListener('mousemove', function (ev) {
  var x = ev.offsetX, y = ev.offsetY;
  if (dragging) { setFromPos(x, y); return; }
  var h = hitTest(x, y);
  if (h) { _cv.style.cursor = 'pointer'; showTooltip(h.tip, ev); return; }
  if (inArea(x, y)) {
    _cv.style.cursor = 'crosshair';
    var u = (x - gArea.left) / (gArea.right - gArea.left), v = (gArea.bottom - y) / (gArea.bottom - gArea.top);
    var T = Tu(u), p = Pv(v);
    showTooltip('T = ' + fmtT(T) + ' °C, p = ' + fmtP(p) + ' atm → ' + PHASE[phaseOf(T, p)].name, ev);
  } else { _cv.style.cursor = 'default'; hideTooltip(); }
});
_cv.addEventListener('mouseleave', function () { hideTooltip(); dragging = false; });
_cv.addEventListener('mousedown', function (ev) {
  var x = ev.offsetX, y = ev.offsetY;
  var h = hitTest(x, y);
  if (h) { showPopup(h.title, h.popup); return; }
  if (inArea(x, y)) { stopAnim(); dragging = true; setFromPos(x, y); }
});
window.addEventListener('mouseup', function () { dragging = false; });

document.addEventListener('fig-resize', function () { chart.resize(); redraw(); });

/* ============ init ============ */
applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: The pressure–temperature phase diagram of water: the coexistence curves divide p–T space into solid, liquid, and vapor regions, so a substance's phase is fixed entirely by where its state point sits relative to those curves.
KEY INSIGHT (what students should walk away understanding): Phase isn't a property you carry with you — it's a location: the state point's position relative to the coexistence curves decides everything, which is why water's uniquely left-leaning melting line lets pressure alone turn ice into liquid.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "The pressure–temperature phase diagram of water: the coexistence curves divide p–T space into solid, liquid, and vapor regions, so a substance's phase is fixed entirely by where its state point sits relative to those curves.",
  "figureType": "line_plot",
  "elements": [
    "Title 'H2O' centered above the plot",
    "Vertical axis with arrowhead labeled 'Pressure, p (atm)' with nonlinear (quasi-logarithmic) ticks at 0.006, 1, and 218",
    "Horizontal axis with arrowhead labeled 'Temperature, T (°C)' with nonlinear ticks at 0, 0.01, 100, and 374",
    "Red fusion (melting) curve: rises nearly vertically from the triple point, leaning slightly LEFT (negative slope), off the top of the plot",
    "Red vaporization (boiling) curve: sweeps up and right from the triple point to the critical point",
    "Red sublimation curve: continues from the triple point down and left toward the origin corner",
    "Filled black dot at the triple point (0.01 °C, 0.006 atm) with label 'Triple point'",
    "Filled black dot at the critical point (374 °C, 218 atm) with label 'Critical point'",
    "Dashed guide lines from the triple point to both axes (to 0.006 atm and to 0.01 °C)",
    "Dashed guide lines from the critical point to both axes (to 218 atm and to 374 °C)",
    "Dashed guide lines marking the 1 atm / 100 °C crossing on the vaporization curve",
    "Italic region labels: 's' (solid, upper-left region), 'l' (liquid, wedge between melting and boiling curves), 'v' (vapor, lower-right region)",
    "Curved arrow annotations labeled 'Melting', 'Boiling', and 'Sublimation' pointing at the three red branches",
    "Movable state-point marker (open circle) with a live readout of T, p and current phase",
    "Highlight shading for whichever region the state point occupies",
    "Horizontal dashed path line with arrow for the selected heating path (1 atm, low-pressure, supercritical)"
  ],
  "interactions": [
    {
      "id": "temperature",
      "type": "slider",
      "teaches": "Moving horizontally across the diagram at fixed pressure crosses coexistence curves and changes the phase — the same substance is ice, water, or steam depending only on where it lands.",
      "label": "Temperature T (°C)",
      "range": [
        -20,
        500,
        1
      ],
      "default": 25
    },
    {
