// @FIGURE_CODE_BEGIN
/* ================= helpers ================= */
var RED = '#e8423c';
function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }
var L10 = function (x) { return Math.log(x) / Math.LN10; };

/* monotone cubic (Fritsch–Carlson) — C1 smooth axis warp, no kinks */
function mono(P) {
  var n = P.length, xs = [], ys = [], i;
  for (i = 0; i < n; i++) { xs.push(P[i][0]); ys.push(P[i][1]); }
  var d = [], m = [];
  for (i = 0; i < n - 1; i++) d.push((ys[i + 1] - ys[i]) / (xs[i + 1] - xs[i]));
  m.push(d[0]);
  for (i = 1; i < n - 1; i++) {
    if (d[i - 1] * d[i] <= 0) { m.push(0); }
    else {
      var w1 = 2 * (xs[i + 1] - xs[i]) + (xs[i] - xs[i - 1]);
      var w2 = (xs[i + 1] - xs[i]) + 2 * (xs[i] - xs[i - 1]);
      var mm = (w1 + w2) / (w1 / d[i - 1] + w2 / d[i]);
      var lim = 3 * Math.min(Math.abs(d[i - 1]), Math.abs(d[i]));
      m.push(Math.abs(mm) > lim ? (mm > 0 ? lim : -lim) : mm);
    }
  }
  m.push(d[n - 2]);
  function at(x) {
    x = cl(x, xs[0], xs[n - 1]);
    var k = 0; while (k < n - 2 && x > xs[k + 1]) k++;
    var h = xs[k + 1] - xs[k], t = (x - xs[k]) / h, t2 = t * t, t3 = t2 * t;
    return (2 * t3 - 3 * t2 + 1) * ys[k] + (t3 - 2 * t2 + t) * h * m[k] +
      (-2 * t3 + 3 * t2) * ys[k + 1] + (t3 - t2) * h * m[k + 1];
  }
  function inv(y) {
    y = cl(y, ys[0], ys[n - 1]);
    var a = xs[0], b = xs[n - 1];
    for (var k = 0; k < 60; k++) { var mid = (a + b) / 2; if (at(mid) < y) a = mid; else b = mid; }
    return (a + b) / 2;
  }
  return { at: at, inv: inv };
}

/* nonlinear (schematic, log-like) axes: ticks 0 / 0.01 / 100 / 374 and 0.006 / 1 / 218 */
var TW = mono([[-25, 0], [-12, 0.10], [-5, 0.163], [0, 0.21], [0.01, 0.30], [10, 0.35],
[40, 0.46], [100, 0.683], [160, 0.79], [260, 0.87], [374, 0.932], [520, 1]]);
var PW = mono([[-3, 0], [-2.75, 0.125], [-2.2218, 0.355], [-1.8, 0.408], [-1, 0.458],
[0, 0.535], [1, 0.663], [1.8, 0.80], [2.3385, 0.94], [2.602, 1]]);
function uT(T) { return TW.at(T); }
function Tu(u) { return TW.inv(u); }
function vP(p) { return PW.at(L10(cl(p, 0.001, 400))); }
function Pv(v) { return Math.pow(10, PW.inv(v)); }

/* ================= physics / geometry of the coexistence curves ================= */
var PT = 0.006, TT = 0.01, PC = 218, TC = 374;
function pVap(T) { return Math.exp(11.933 - 3975 / (T + 233.15)); }   // 100°C→1atm, 374°C→218atm
function tVap(p) { return 3975 / (11.933 - Math.log(p)) - 233.15; }
function tSub(p) { return 6135 / (17.34 - Math.log(p)) - 273.15; }

var uTP = uT(TT), vTP = vP(PT), uCP = uT(TC), vCP = vP(PC);
var MELT_TOP = 0.14;                       // exaggerated left lean (see reconstruction notes)
function uMeltU(v) {                       // fusion curve, drawn smoothly in normalized space
  var s = cl((v - vTP) / (1 - vTP), 0, 1);
  return uTP - (uTP - MELT_TOP) * Math.pow(s, 1.2);
}
var uSUB0 = uT(tSub(0.001));
function uSubU(v) {
  var s = cl(v / vTP, 0, 1);
  return uSUB0 + (uTP - uSUB0) * Math.pow(s, 0.95);
}

var meltPts = [], vapPts = [], subPts = [];
(function () {
  var i, v, T;
  for (i = 0; i <= 160; i++) { v = vTP + (1 - vTP) * i / 160; meltPts.push({ x: uMeltU(v), y: v }); }
  for (i = 0; i <= 120; i++) { v = vTP * i / 120; subPts.push({ x: uSubU(v), y: v }); }
  for (i = 0; i <= 420; i++) { T = TT + (TC - TT) * i / 420; vapPts.push({ x: uT(T), y: vP(pVap(T)) }); }
})();
function uAtV(pts, v) {
  var best = pts[0], bd = 1e9;
  for (var i = 0; i < pts.length; i++) { var d = Math.abs(pts[i].y - v); if (d < bd) { bd = d; best = pts[i]; } }
  return best.x;
}

function phaseOf(T, p) {
  if (Math.abs(T - TT) < 0.03 && Math.abs(L10(p) - L10(PT)) < 0.03) return 'triple';
  var u = uT(T), v = vP(p);
  if (p >= PT) {
    if (u <= uMeltU(v)) return 'solid';
    if (T >= TC && p >= PC) return 'super';
    if (p >= PC) return 'liquid';
    if (T >= TC) return 'vapor';
    return (p > pVap(T)) ? 'liquid' : 'vapor';
  }
  return (u <= uSubU(v)) ? 'solid' : 'vapor';
}
var PHASE = {
  solid: { name: 'Solid (ice)', fill: 'rgba(120,152,192,0.15)', c: '#41618f' },
  liquid: { name: 'Liquid (water)', fill: 'rgba(72,140,216,0.13)', c: '#1a6bbd' },
  vapor: { name: 'Vapor (steam)', fill: 'rgba(240,190,80,0.18)', c: '#a9760a' },
  super: { name: 'Supercritical fluid', fill: 'rgba(152,112,206,0.15)', c: '#7038b0' },
  triple: { name: 'Triple point: ice + water + vapor', fill: null, c: '#333' }
};

/* ================= state ================= */
var state = { T: 25, p: 1, path: null };
var anim = null, dragging = false;
var gArea = null, gFs = 12, gS = 400;
var scrCurves = { melt: [], vap: [], sub: [] };
var PATHS = {
  'Free explore': null, '1 atm path': 1,
  'Low-pressure path (0.003 atm)': 0.003, 'Supercritical path (250 atm)': 250
};

/* ================= canvas ================= */
var _cv = document.createElement('canvas');
_cv.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(_cv);
function PXu(u) { return gArea.left + u * (gArea.right - gArea.left); }
function PYv(v) { return gArea.bottom - v * (gArea.bottom - gArea.top); }

function txt(ctx, s, x, y, o) {
  o = o || {};
  ctx.save();
  ctx.font = o.font || (gFs + 'px sans-serif');
  ctx.textAlign = o.align || 'left';
  ctx.textBaseline = o.baseline || 'alphabetic';
  if (o.halo !== false) {
    ctx.lineWidth = o.haloW || 3.2; ctx.strokeStyle = '#fff';
    ctx.lineJoin = 'round'; ctx.strokeText(s, x, y);
  }
  ctx.fillStyle = o.color || '#000';
  ctx.fillText(s, x, y);
  ctx.restore();
}
function seg(ctx, x1, y1, x2, y2) { ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke(); }
function head(ctx, x, y, ang, s) {
  ctx.save(); ctx.translate(x, y); ctx.rotate(ang);
  ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-s, s * 0.42); ctx.lineTo(-s, -s * 0.42);
  ctx.closePath(); ctx.fill(); ctx.restore();
}
function curveArrow(ctx, x0, y0, cx, cy, x1, y1, s) {
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.quadraticCurveTo(cx, cy, x1, y1); ctx.stroke();
  head(ctx, x1, y1, Math.atan2(y1 - cy, x1 - cx), s);
}
function fillPoly(ctx, pts, color) {
  if (!pts.length || !color) return;
  ctx.beginPath(); ctx.moveTo(PXu(pts[0][0]), PYv(pts[0][1]));
  for (var i = 1; i < pts.length; i++) ctx.lineTo(PXu(pts[i][0]), PYv(pts[i][1]));
  ctx.closePath(); ctx.fillStyle = color; ctx.fill();
}
function asArr(a) { return a.map(function (p) { return [p.x, p.y]; }); }
function regionPoly(ph) {
  var um = uMeltU(1);
  if (ph === 'solid') return [[0, 0], [uSUB0, 0]].concat(asArr(subPts)).concat(asArr(meltPts)).concat([[um, 1], [0, 1]]);
  if (ph === 'liquid') return asArr(meltPts).concat([[um, 1], [uCP, 1], [uCP, vCP]]).concat(asArr(vapPts).reverse());
  if (ph === 'vapor') return [[uSUB0, 0]].concat(asArr(subPts)).concat(asArr(vapPts)).concat([[1, vCP], [1, 0]]);
  if (ph === 'super') return [[uCP, vCP], [1, vCP], [1, 1], [uCP, 1]];
  return [];
}
function crossings(p) {
  var out = [];
  if (p >= PT) {
    out.push({ u: uMeltU(vP(p)), label: 'melting', T: Tu(uMeltU(vP(p))) });
    if (p <= PC) { var tb = tVap(p); if (tb < 500) out.push({ u: uT(tb), label: 'boiling', T: tb }); }
  } else {
    out.push({ u: uSubU(vP(p)), label: 'sublimation', T: Tu(uSubU(vP(p))) });
  }
  return out;
}

/* ---------- background: region tint, path line, dashed guides ---------- */
var bgPlugin = {
  id: 'bgw',
  beforeDatasetsDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea; gArea = a;
    var S = Math.min(chart.width, chart.height); gS = S;
    var ph = phaseOf(state.T, state.p);
    ctx.save();
    ctx.beginPath(); ctx.rect(a.left, a.top, a.right - a.left, a.bottom - a.top); ctx.clip();
    if (PHASE[ph].fill) fillPoly(ctx, regionPoly(ph), PHASE[ph].fill);

    if (state.path) {                       /* selected heating path */
      var y = PYv(vP(state.path));
      ctx.setLineDash([6, 4]); ctx.strokeStyle = '#555'; ctx.fillStyle = '#555';
      ctx.lineWidth = cl(S * 0.0026, 1, 2);
      seg(ctx, a.left + 2, y, a.right - 10, y);
      ctx.setLineDash([]);
      head(ctx, a.right - 2, y, 0, cl(S * 0.018, 5, 9));
    }

    ctx.setLineDash([4, 3]);                /* thin dashed guides */
    ctx.strokeStyle = '#222'; ctx.lineWidth = cl(S * 0.002, 0.8, 1.2);
    var xt = PXu(uTP), yt = PYv(vTP);
    seg(ctx, a.left, yt, xt, yt); seg(ctx, xt, yt, xt, a.bottom);
    var xc = PXu(uCP), yc = PYv(vCP);
    seg(ctx, a.left, yc, xc, yc); seg(ctx, xc, yc, xc, a.bottom);
    var x1 = PXu(uT(100)), y1 = PYv(vP(1));
    seg(ctx, a.left, y1, x1, y1); seg(ctx, x1, y1, x1, a.bottom);
    ctx.setLineDash([]);
    ctx.restore();
  }
};

/* ---------- foreground: axes, labels, marker ---------- */
var fgPlugin = {
  id: 'fgw',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea; gArea = a;
    var S = Math.min(chart.width, chart.height); gS = S;
    gFs = cl(S * 0.030, 8, 14);
    var fs = gFs;
    var lw = cl(S * 0.0025, 1, 1.9);
    var tk = cl(S * 0.012, 3, 6);
    var ext = cl(S * 0.038, 10, 20);
    var ah = cl(S * 0.020, 5, 10);
    var i;

    function toScr(arr) { return arr.map(function (p) { return [PXu(p.x), PYv(p.y)]; }); }
    scrCurves.melt = toScr(meltPts); scrCurves.vap = toScr(vapPts); scrCurves.sub = toScr(subPts);

    ctx.save();
    ctx.font = fs + 'px sans-serif';
    ctx.lineWidth = lw; ctx.strokeStyle = '#000'; ctx.fillStyle = '#000';

    /* axes with arrowheads */
    seg(ctx, a.left, a.bottom, a.left, a.top - ext + ah);
    head(ctx, a.left, a.top - ext, -Math.PI / 2, ah);
    seg(ctx, a.left, a.bottom, a.right + ext - ah, a.bottom);
    head(ctx, a.right + ext, a.bottom, 0, ah);

    /* ticks */
    var yT = [[218, '218'], [1, '1'], [0.006, '0.006']], maxLW = 0;
    for (i = 0; i < yT.length; i++) maxLW = Math.max(maxLW, ctx.measureText(yT[i][1]).width);
    for (i = 0; i < yT.length; i++) {
      var yy = PYv(vP(yT[i][0]));
      ctx.strokeStyle = '#000'; seg(ctx, a.left - tk, yy, a.left, yy);
      txt(ctx, yT[i][1], a.left - tk - 3, yy, { align: 'right', baseline: 'middle', font: fs + 'px sans-serif' });
    }
    var xT = [[0, '0'], [0.01, '0.01'], [100, '100'], [374, '374']];
    for (i = 0; i < xT.length; i++) {
      var xx = PXu(uT(xT[i][0]));
      ctx.strokeStyle = '#000'; seg(ctx, xx, a.bottom, xx, a.bottom + tk);
      txt(ctx, xT[i][1], xx, a.bottom + tk + 2, { align: 'center', baseline: 'top', font: fs + 'px sans-serif' });
    }

    /* axis titles + figure title */
    var xTit = Math.max(fs * 0.9, a.left - maxLW - tk - fs * 1.35);
    ctx.save();
    ctx.translate(xTit, (a.top + a.bottom) / 2); ctx.rotate(-Math.PI / 2);
    txt(ctx, 'Pressure, p (atm)', 0, 0, { align: 'center', baseline: 'middle', font: 'bold ' + fs + 'px sans-serif' });
    ctx.restore();
    txt(ctx, 'Temperature, T (°C)', (a.left + a.right) / 2, Math.min(chart.height - 3, a.bottom + tk + fs * 2.6),
      { align: 'center', baseline: 'alphabetic', font: 'bold ' + fs + 'px sans-serif' });
    txt(ctx, 'H₂O', (a.left + a.right) / 2, Math.max(fs * 1.3, a.top * 0.62),
      { align: 'center', baseline: 'alphabetic', font: 'bold ' + (fs * 1.25) + 'px sans-serif' });

    /* italic region letters */
    var rf = 'italic ' + (fs * 1.3) + 'px Georgia, serif';
    txt(ctx, 's', PXu(0.105), PYv(0.42), { align: 'center', baseline: 'middle', font: rf });
    txt(ctx, 'l', PXu(0.46), PYv(0.72), { align: 'center', baseline: 'middle', font: rf });
    txt(ctx, 'v', PXu(0.74), PYv(0.39), { align: 'center', baseline: 'middle', font: rf });

    /* special points */
    var rdot = cl(S * 0.0115, 3, 6);
    var xt = PXu(uTP), yt = PYv(vTP), xc = PXu(uCP), yc = PYv(vCP);
    ctx.fillStyle = '#000';
    ctx.beginPath(); ctx.arc(xt, yt, rdot, 0, 6.2832); ctx.fill();
    ctx.beginPath(); ctx.arc(xc, yc, rdot, 0, 6.2832); ctx.fill();
    txt(ctx, 'Triple', xt + rdot + 4, yt + fs * 1.0, { font: fs + 'px sans-serif' });
    txt(ctx, 'point', xt + rdot + 4, yt + fs * 2.1, { font: fs + 'px sans-serif' });
    ctx.font = fs + 'px sans-serif';
    var cpw = ctx.measureText('Critical point').width;
    var cpx = cl(xc - cpw * 0.55, 3, chart.width - cpw - 3);
    txt(ctx, 'Critical point', cpx, yc - rdot - fs * 0.6, { font: fs + 'px sans-serif' });

    /* outside annotations with curved leader arrows */
    var af = fs * 0.95;
    ctx.font = af + 'px sans-serif';
    while (af > 7 && ctx.measureText('Sublimation').width > a.left - 6) { af -= 0.5; ctx.font = af + 'px sans-serif'; }
    var annF = af + 'px sans-serif';
    ctx.lineWidth = cl(S * 0.0022, 0.9, 1.6); ctx.strokeStyle = '#000'; ctx.fillStyle = '#000';
    var hs = cl(S * 0.016, 4, 8);

    var mTx = PXu(uMeltU(0.80)), mTy = PYv(0.80);
    var mtw = ctx.measureText('Melting').width;
    var mx = Math.max(mtw + 3, a.left - maxLW - tk - 8);
    txt(ctx, 'Melting', mx, PYv(0.885), { align: 'right', baseline: 'middle', font: annF });
    curveArrow(ctx, mx + 5, PYv(0.885), (mx + mTx) / 2, PYv(0.855), mTx - 6, mTy, hs);

    var stw = ctx.measureText('Sublimation').width;
    var sx = Math.max(stw + 3, a.left - 6);
    txt(ctx, 'Sublimation', sx, PYv(0.045), { align: 'right', baseline: 'middle', font: annF });
    var sTx = PXu(uSubU(0.13)), sTy = PYv(0.13);
    curveArrow(ctx, sx + 5, PYv(0.045), (sx + sTx) / 2 + 6, PYv(0.032), sTx - 4, sTy + 4, hs);

    var btw = ctx.measureText('Boiling').width;
    var bx = Math.min(a.right + 8, chart.width - btw - 3);
    txt(ctx, 'Boiling', bx, PYv(0.545), { align: 'left', baseline: 'middle', font: annF });
    var bTx = PXu(uAtV(vapPts, 0.665)), bTy = PYv(0.665);
