    if (state.path) {
      var yp = PYv(vP(state.path)), cs = crossings(state.path);
      for (i = 0; i < cs.length; i++) {
        var cxp = PXu(cs[i].u);
        if (cxp < a.left || cxp > a.right) continue;
        ctx.strokeStyle = '#333'; ctx.lineWidth = cl(S * 0.0026, 1, 2);
        seg(ctx, cxp, yp - hs, cxp, yp + hs);
        var done = state.T >= cs[i].T;
        txt(ctx, cs[i].label, cxp, yp - hs - 3, {
          align: 'center', baseline: 'alphabetic',
