window.__markRendered();

/* ================= formatting / setters ================= */
function fmtT(T) {
  if (Math.abs(T) < 0.1 && T !== 0) return T.toFixed(3);
  if (Math.abs(T) < 10) return T.toFixed(1);
  return T.toFixed(0);
}
function fmtP(p) {
  if (p < 0.01) return p.toFixed(4);
  if (p < 1) return p.toFixed(3);
  if (p < 10) return p.toFixed(2);
  return p.toFixed(0);
}
function setT(T) {
  state.T = T;
  document.getElementById('temperatureInput').value = String(T);
  document.getElementById('temperatureVal').value = fmtT(T);
}
function setP(p) {
  state.p = p;
  document.getElementById('pressureInput').value = String(cl(L10(p), -3, 2.477));
  document.getElementById('pressureVal').value = fmtP(p);
}
function redraw() {
  var ph = phaseOf(state.T, state.p);
  document.getElementById('stateReadout').textContent =
    'T = ' + fmtT(state.T) + ' °C   p = ' + fmtP(state.p) + ' atm';
  var el = document.getElementById('phaseReadout');
  el.textContent = PHASE[ph].name;
  el.style.color = PHASE[ph].c;
  chart.update('none');
}
function stopAnim() { if (anim) { cancelAnimationFrame(anim); anim = null; } }

/* ================= controls ================= */
function update_temperature(v) { stopAnim(); state.T = v; redraw(); }
function update_pressure(lg) {
  stopAnim();
  var p = cl(Math.pow(10, lg), 0.001, 300);
  state.p = p;
  document.getElementById('pressureVal').value = fmtP(p);
  redraw();
}
function applyPath(name) {
  state.path = PATHS[name] || null;
  var pi = document.getElementById('pressureInput');
  if (state.path) { setP(state.path); pi.disabled = true; } else { pi.disabled = false; }
}
function toggle_heatingPath(v) { stopAnim(); applyPath(v); redraw(); }
function pathEndT() {
  var p = state.p;
  if (p > PC) return 470;
  if (p < PT) return 140;
  return cl(tVap(p) + 80, 130, 470);
}
function animateTo(target) {
  stopAnim();
  var from = state.T, t0 = performance.now(), dur = 3500;
  function frame(now) {
    var k = cl((now - t0) / dur, 0, 1);
    setT(Math.round((from + (target - from) * k) * 100) / 100);
    redraw();
    anim = (k < 1) ? requestAnimationFrame(frame) : null;
  }
  anim = requestAnimationFrame(frame);
}
function trigger_tracePath() { stopAnim(); var end = pathEndT(); setT(-20); redraw(); animateTo(end); }

/* ================= demo steps ================= */
var STEPS = [
  {
    title: 'Read the map', narration: 'Three red curves carve the plane into solid (s), liquid (l) and vapor (v). The state point sits at room conditions, 25 °C and 1 atm, inside the liquid wedge — water is liquid there for no other reason than its location on this map.',
    state: { temperature: 25, pressure: 1, heatingPath: 'Free explore' }
  },
  {
    title: 'Cross the boiling curve', narration: 'Slide the temperature right at 1 atm. At 100 °C the point crosses the vaporization curve and the tinted region flips from liquid to vapor — that crossing is boiling.',
    state: { temperature: 130, pressure: 1, heatingPath: 'Free explore' }
  },
  {
    title: 'The triple point', narration: 'Drop the pressure to 0.006 atm and the temperature to 0.01 °C. All three curves meet at this single dot, the one condition where ice, water and steam coexist.',
    state: { temperature: 0.01, pressure: 0.006, heatingPath: 'Free explore' }
  },
  {
    title: 'Squeeze ice into water', narration: 'Park the temperature just below 0 °C, in the solid region at 1 atm, then raise the pressure to ~250 atm. Because water\u2019s melting curve leans LEFT, climbing vertically crosses it and the label changes from solid to liquid — pressure alone melts ice.',
    state: { temperature: -2, pressure: 250, heatingPath: 'Free explore' }
  },
  {
    title: 'Sublimation path', narration: 'Choose the low-pressure path, below the triple-point pressure, and heat. The point crosses only the sublimation curve: ice turns straight into vapor with no liquid stage.',
    state: { heatingPath: 'Low-pressure path (0.003 atm)', pressure: 0.003, temperature: 20 }
  },
  {
    title: 'Past the critical point', narration: 'Now take the supercritical path above 218 atm and heat past 374 °C. No boundary is crossed — liquid and vapor merge continuously into one indistinguishable supercritical fluid.',
    state: { heatingPath: 'Supercritical path (250 atm)', pressure: 250, temperature: 450 }
  }
];
var curStep = 0;
function applyStep(i) {
  stopAnim();
  curStep = (i + STEPS.length) % STEPS.length;
  var s = STEPS[curStep], st = s.state;
  if (st.heatingPath !== undefined) {
    document.getElementById('heatingPathInput').value = st.heatingPath;
    applyPath(st.heatingPath);
  }
  if (st.pressure !== undefined) setP(st.pressure);
  if (st.temperature !== undefined) setT(st.temperature);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + STEPS.length + ' · ' + s.title;
  redraw();
  if (st.heatingPath && st.heatingPath !== 'Free explore') {
    setT(-20); redraw();
    setTimeout(function () { animateTo(st.temperature); }, 350);
  }
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

/* ================= hover / click / drag ================= */
function dist2seg(px, py, x1, y1, x2, y2) {
  var dx = x2 - x1, dy = y2 - y1, L = dx * dx + dy * dy;
  var t = L ? cl(((px - x1) * dx + (py - y1) * dy) / L, 0, 1) : 0;
  var ax = x1 + t * dx - px, ay = y1 + t * dy - py;
  return Math.sqrt(ax * ax + ay * ay);
}
function nearCurve(pts, x, y) {
  var m = 1e9;
  for (var i = 1; i < pts.length; i++) m = Math.min(m, dist2seg(x, y, pts[i - 1][0], pts[i - 1][1], pts[i][0], pts[i][1]));
  return m;
}
function inArea(x, y) { return gArea && x >= gArea.left && x <= gArea.right && y >= gArea.top && y <= gArea.bottom; }
function hitTest(x, y) {
  if (!gArea) return null;
  var r = cl(gS * 0.03, 8, 14);
  var xt = PXu(uTP), yt = PYv(vTP), xc = PXu(uCP), yc = PYv(vCP);
  if (Math.hypot(x - xt, y - yt) < r) return {
    tip: 'Triple point — 0.01 °C, 0.006 atm', title: 'Triple point',
    popup: 'At 0.01 °C and 0.006 atm the melting, boiling and sublimation curves all meet. This is the only pressure–temperature combination where ice, liquid water and water vapor coexist in equilibrium.'
  };
  if (Math.hypot(x - xc, y - yc) < r) return {
    tip: 'Critical point — 374 °C, 218 atm', title: 'Critical point',
    popup: 'The vaporization curve ends here at 374 °C and 218 atm. Above the critical point the liquid and vapor densities become equal, so there is no boundary left to cross: the substance is a single supercritical fluid.'
  };
  var th = cl(gS * 0.018, 5, 9);
  if (nearCurve(scrCurves.melt, x, y) < th) return {
    tip: 'Fusion (melting) curve — solid ⇄ liquid', title: 'Melting (fusion) curve',
    popup: 'This boundary separates ice from liquid water. For water it leans to the LEFT (negative slope, exaggerated here) because ice is less dense than liquid, so squeezing ice at constant temperature can push it across the curve and melt it.'
  };
  if (nearCurve(scrCurves.vap, x, y) < th) return {
    tip: 'Vaporization (boiling) curve — liquid ⇄ vapor', title: 'Vaporization curve',
    popup: 'Along this curve liquid and vapor coexist; it gives the boiling temperature at each pressure (100 °C at 1 atm). It starts at the triple point and terminates at the critical point, where the distinction between liquid and vapor disappears.'
  };
  if (nearCurve(scrCurves.sub, x, y) < th) return {
    tip: 'Sublimation curve — solid ⇄ vapor', title: 'Sublimation curve',
    popup: 'Below the triple-point pressure of 0.006 atm no liquid can exist. Heating ice at such low pressure carries the state point across this curve, and the solid passes directly into vapor — sublimation.'
  };
  return null;
}
function setFromPos(x, y) {
  var u = cl((x - gArea.left) / (gArea.right - gArea.left), 0, 1);
  var v = cl((gArea.bottom - y) / (gArea.bottom - gArea.top), 0, 1);
  var T = Tu(u);
  T = (Math.abs(T) < 2) ? Math.round(T * 1000) / 1000 : Math.round(T * 10) / 10;
  setT(cl(T, -20, 500));
  if (!state.path) setP(cl(Pv(v), 0.001, 300));
  redraw();
}
_cv.addEventListener('mousemove', function (ev) {
  var x = ev.offsetX, y = ev.offsetY;
  if (dragging) { setFromPos(x, y); return; }
  var h = hitTest(x, y);
  if (h) { _cv.style.cursor = 'pointer'; showTooltip(h.tip, ev); return; }
  if (inArea(x, y)) {
    _cv.style.cursor = 'crosshair';
    var u = (x - gArea.left) / (gArea.right - gArea.left), v = (gArea.bottom - y) / (gArea.bottom - gArea.top);
    var T = Tu(u), p = Pv(v);
    showTooltip('T = ' + fmtT(T) + ' °C, p = ' + fmtP(p) + ' atm → ' + PHASE[phaseOf(T, p)].name, ev);
  } else { _cv.style.cursor = 'default'; hideTooltip(); }
});
_cv.addEventListener('mouseleave', function () { hideTooltip(); dragging = false; });
_cv.addEventListener('mousedown', function (ev) {
  var x = ev.offsetX, y = ev.offsetY, h = hitTest(x, y);
  if (h) { showPopup(h.title, h.popup); return; }
  if (inArea(x, y)) { stopAnim(); dragging = true; setFromPos(x, y); }
});
window.addEventListener('mouseup', function () { dragging = false; });
document.addEventListener('fig-resize', function () { chart.resize(); redraw(); });

/* ================= init ================= */
applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
