Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:bold;font-size:12px">H₂O phase diagram — guided demo</span>
<span id="demoNarration" style="display:block;font-size:11px;line-height:1.45;min-height:80px"></span>
<span style="display:flex;gap:6px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px;flex:1;text-align:center"></span>
  <button onclick="nextStep()">▶</button>
</span>
<label>Temperature <i>T</i> (°C): <output id="temperatureVal">25</output>
  <input id="temperatureInput" type="range" min="0.022" max="0.9" step="0.0005" value="0.408" oninput="update_temperature(+this.value)">
</label>
<label>Pressure <i>p</i> (atm): <output id="pressureVal">1.00</output>
  <input id="pressureInput" type="range" min="-3" max="2.477" step="0.002" value="0" oninput="update_pressure(+this.value)">
</label>
<label>Heating path
  <select id="heatingPathInput" onchange="toggle_heatingPath(this.value)">
    <option>Free explore</option>
    <option>1 atm path</option>
    <option>Low-pressure path (0.003 atm)</option>
    <option>Supercritical path (250 atm)</option>
  </select>
</label>
<button onclick="trigger_tracePath()">▶ Heat the sample along the path</button>
<span style="font-size:11px;border-top:1px solid #dcdfe3;padding-top:5px"><b>State point</b></span>
<span id="stateReadout" style="font-size:11px;font-family:ui-monospace,Consolas,monospace"></span>
<span id="phaseReadout" style="font-size:12px;font-weight:bold"></span>
<span style="font-size:10px;color:#666;line-height:1.35">Drag inside the plot to move the state point. Hover curves and dots for detail; click them for an explanation. Both axes are schematic and strongly compressed, so values close to 0 °C and 0.006 atm are stretched apart.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ================= helpers ================= */
var RED = '#e8423c';
function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }
var L10 = function (x) { return Math.log(x) / Math.LN10; };

/* monotone cubic (Fritsch–Carlson) — C1 smooth warp, no kinks */
function mono(P) {
  var n = P.length, xs = [], ys = [], i;
  for (i = 0; i < n; i++) { xs.push(P[i][0]); ys.push(P[i][1]); }
  var d = [], m = [];
  for (i = 0; i < n - 1; i++) d.push((ys[i + 1] - ys[i]) / (xs[i + 1] - xs[i]));
  m.push(d[0]);
  for (i = 1; i < n - 1; i++) {
    if (d[i - 1] * d[i] <= 0) { m.push(0); }
    else {
      var w1 = 2 * (xs[i + 1] - xs[i]) + (xs[i] - xs[i - 1]);
      var w2 = (xs[i + 1] - xs[i]) + 2 * (xs[i] - xs[i - 1]);
      var mm = (w1 + w2) / (w1 / d[i - 1] + w2 / d[i]);
      var lim = 3 * Math.min(Math.abs(d[i - 1]), Math.abs(d[i]));
      m.push(Math.abs(mm) > lim ? (mm > 0 ? lim : -lim) : mm);
    }
  }
  m.push(d[n - 2]);
  function at(x) {
    x = cl(x, xs[0], xs[n - 1]);
    var k = 0; while (k < n - 2 && x > xs[k + 1]) k++;
    var h = xs[k + 1] - xs[k], t = (x - xs[k]) / h, t2 = t * t, t3 = t2 * t;
    return (2 * t3 - 3 * t2 + 1) * ys[k] + (t3 - 2 * t2 + t) * h * m[k] +
      (-2 * t3 + 3 * t2) * ys[k + 1] + (t3 - t2) * h * m[k + 1];
  }
  function inv(y) {
    y = cl(y, ys[0], ys[n - 1]);
    var a = xs[0], b = xs[n - 1];
    for (var k = 0; k < 60; k++) { var mid = (a + b) / 2; if (at(mid) < y) a = mid; else b = mid; }
    return (a + b) / 2;
  }
  return { at: at, inv: inv };
}

/* nonlinear (schematic, log-like) axes — knots taken from the source figure */
var TW = mono([[-25, 0], [-20, 0.022], [-10, 0.075], [-5, 0.106], [0, 0.148], [0.005, 0.2155],
[0.01, 0.283], [1, 0.315], [10, 0.355], [40, 0.46], [100, 0.646], [180, 0.737],
[260, 0.789], [374, 0.831], [470, 0.885], [600, 0.95], [760, 1]]);
var PW = mono([[-4, 0], [-3.1, 0.18], [-2.2218, 0.348], [-1.2, 0.44], [0, 0.522],
[1, 0.645], [1.8, 0.78], [2.1, 0.86], [2.3385, 0.94], [2.7, 1]]);
function uT(T) { return TW.at(T); }
function Tu(u) { return TW.inv(u); }
function vP(p) { return PW.at(L10(cl(p, 1e-4, 450))); }
function Pv(v) { return Math.pow(10, PW.inv(v)); }

/* ============ coexistence curves (normalized plot coordinates) ============ */
var PT = 0.006, TT = 0.01, PC = 218, TC = 374;
var uTP = uT(TT), vTP = vP(PT), uCP = uT(TC), vCP = vP(PC);

/* vaporization: smooth convex sweep TP → (100 °C, 1 atm) → critical point */
var VAP = mono([[0.283, 0.348], [0.37, 0.375], [0.46, 0.411], [0.554, 0.459], [0.646, 0.522],
[0.723, 0.600], [0.775, 0.685], [0.815, 0.820], [0.831, 0.940]]);
function pVap(T) { return Pv(VAP.at(cl(uT(T), uTP, uCP))); }
function tVap(p) { return Tu(VAP.inv(cl(vP(p), vTP, vCP))); }

/* fusion: nearly vertical, small but clear LEFT lean (matches source) */
var MELT_TOP = 0.209;
function uMeltU(v) {
  var s = cl((v - vTP) / (1 - vTP), 0, 1);
  return uTP - (uTP - MELT_TOP) * Math.pow(s, 0.40);
}
/* sublimation: terminates exactly at the bottom-left axis corner */
var uSUB0 = 0.0246;
function uSubU(v) {
  var s = cl(v / vTP, 0, 1);
  return uSUB0 + (uTP - uSUB0) * Math.pow(s, 1.20);
}

var meltPts = [], vapPts = [], subPts = [];
(function () {
  var i, v, u;
  for (i = 0; i <= 200; i++) { v = vTP + (1 - vTP) * i / 200; meltPts.push({ x: uMeltU(v), y: v }); }
  for (i = 0; i <= 140; i++) { v = vTP * i / 140; subPts.push({ x: uSubU(v), y: v }); }
  for (i = 0; i <= 320; i++) { u = uTP + (uCP - uTP) * i / 320; vapPts.push({ x: u, y: VAP.at(u) }); }
})();

function phaseOf(T, p) {
  var u = uT(T), v = vP(p);
  if (Math.abs(u - uTP) < 0.012 && Math.abs(v - vTP) < 0.012) return 'triple';
  if (v < vTP) return (u <= uSubU(v)) ? 'solid' : 'vapor';
  if (u <= uMeltU(v)) return 'solid';
  if (u >= uCP) return (v >= vCP) ? 'super' : 'vapor';
  if (v >= vCP) return 'liquid';
  return (v > VAP.at(u)) ? 'liquid' : 'vapor';
}
var PHASE = {
  solid: { name: 'Solid (ice)', fill: 'rgba(120,152,192,0.15)', c: '#41618f' },
  liquid: { name: 'Liquid (water)', fill: 'rgba(72,140,216,0.13)', c: '#1a6bbd' },
  vapor: { name: 'Vapor (steam)', fill: 'rgba(240,190,80,0.18)', c: '#a9760a' },
  super: { name: 'Supercritical fluid', fill: 'rgba(152,112,206,0.15)', c: '#7038b0' },
  triple: { name: 'Triple point: ice + water + vapor', fill: null, c: '#333' }
};

/* ================= state ================= */
var state = { T: 25, p: 1, path: null };
var anim = null, dragging = false, touched = false;
var gArea = null, gFs = 12, gS = 400;
var scrCurves = { melt: [], vap: [], sub: [] };
var PATHS = {
  'Free explore': null, '1 atm path': 1,
  'Low-pressure path (0.003 atm)': 0.003, 'Supercritical path (250 atm)': 250
};

/* ================= canvas ================= */
var _cv = document.createElement('canvas');
_cv.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(_cv);
function PXu(u) { return gArea.left + u * (gArea.right - gArea.left); }
function PYv(v) { return gArea.bottom - v * (gArea.bottom - gArea.top); }

function txt(ctx, s, x, y, o) {
  o = o || {};
  ctx.save();
  ctx.font = o.font || (gFs + 'px sans-serif');
  ctx.textAlign = o.align || 'left';
  ctx.textBaseline = o.baseline || 'alphabetic';
  if (o.halo !== false) {
    ctx.lineWidth = o.haloW || 3.2; ctx.strokeStyle = '#fff';
    ctx.lineJoin = 'round'; ctx.strokeText(s, x, y);
  }
  ctx.fillStyle = o.color || '#000';
  ctx.fillText(s, x, y);
  ctx.restore();
}
function seg(ctx, x1, y1, x2, y2) { ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke(); }
function head(ctx, x, y, ang, s) {
  ctx.save(); ctx.translate(x, y); ctx.rotate(ang);
  ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-s, s * 0.42); ctx.lineTo(-s, -s * 0.42);
  ctx.closePath(); ctx.fill(); ctx.restore();
}
function curveArrow(ctx, x0, y0, cx, cy, x1, y1, s) {
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.quadraticCurveTo(cx, cy, x1, y1); ctx.stroke();
  head(ctx, x1, y1, Math.atan2(y1 - cy, x1 - cx), s);
}
function fillPoly(ctx, pts, color) {
  if (!pts.length || !color) return;
  ctx.beginPath(); ctx.moveTo(PXu(pts[0][0]), PYv(pts[0][1]));
  for (var i = 1; i < pts.length; i++) ctx.lineTo(PXu(pts[i][0]), PYv(pts[i][1]));
  ctx.closePath(); ctx.fillStyle = color; ctx.fill();
}
function asArr(a) { return a.map(function (p) { return [p.x, p.y]; }); }
function regionPoly(ph) {
  if (ph === 'solid') return [[0, 0], [uSUB0, 0]].concat(asArr(subPts)).concat(asArr(meltPts)).concat([[0, 1]]);
  if (ph === 'liquid') return asArr(meltPts).concat([[uCP, 1], [uCP, vCP]]).concat(asArr(vapPts).reverse());
  if (ph === 'vapor') return [[uSUB0, 0]].concat(asArr(subPts)).concat(asArr(vapPts)).concat([[1, vCP], [1, 0]]);
  if (ph === 'super') return [[uCP, vCP], [1, vCP], [1, 1], [uCP, 1]];
  return [];
}
function crossings(p) {
  var out = [], v = vP(p);
  if (p >= PT) {
    var um = uMeltU(v);
    out.push({ u: um, label: 'melting', T: Tu(um) });
    if (p <= PC) { var ub = VAP.inv(v); out.push({ u: ub, label: 'boiling', T: Tu(ub) }); }
  } else {
    var us = uSubU(v);
    out.push({ u: us, label: 'sublimation', T: Tu(us) });
  }
  return out;
}

/* ---------- background: region tint, path line, dashed guides ---------- */
var bgPlugin = {
  id: 'bgw',
  beforeDatasetsDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea; gArea = a;
    var S = Math.min(chart.width, chart.height); gS = S;
    ctx.save();
    ctx.beginPath(); ctx.rect(a.left, a.top, a.right - a.left, a.bottom - a.top); ctx.clip();

    if (touched) {                            /* tint only after interaction */
      var ph = phaseOf(state.T, state.p);
      if (PHASE[ph].fill) fillPoly(ctx, regionPoly(ph), PHASE[ph].fill);
    }

    if (state.path) {                         /* selected heating path */
      var y = PYv(vP(state.path));
      ctx.setLineDash([6, 4]); ctx.strokeStyle = '#555'; ctx.fillStyle = '#555';
      ctx.lineWidth = cl(S * 0.0026, 1, 2);
      seg(ctx, a.left + 2, y, a.right - 10, y);
      ctx.setLineDash([]);
      head(ctx, a.right - 2, y, 0, cl(S * 0.018, 5, 9));
    }

    ctx.setLineDash([4, 3]);                  /* thin dashed guides (source) */
    ctx.strokeStyle = '#222'; ctx.lineWidth = cl(S * 0.002, 0.8, 1.2);
    var xt = PXu(uTP), yt = PYv(vTP);
    seg(ctx, a.left, yt, xt, yt); seg(ctx, xt, yt, xt, a.bottom);
    var xc = PXu(uCP), yc = PYv(vCP);
    seg(ctx, a.left, yc, xc, yc); seg(ctx, xc, yc, xc, a.bottom);
    var x1 = PXu(uT(100)), y1 = PYv(vP(1));
    seg(ctx, a.left, y1, x1, y1); seg(ctx, x1, y1, x1, a.bottom);
    ctx.setLineDash([]);
    ctx.restore();
  }
};

/* ---------- foreground: axes, labels, marker ---------- */
var fgPlugin = {
  id: 'fgw',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, a = chart.chartArea; gArea = a;
    var S = Math.min(chart.width, chart.height); gS = S;
    gFs = cl(S * 0.030, 8, 14);
    var fs = gFs;
    var lw = cl(S * 0.0025, 1, 1.9);
    var tk = cl(S * 0.012, 3, 6);
    var ext = cl(S * 0.038, 10, 20);
    var ah = cl(S * 0.020, 5, 10);
    var i;

    function toScr(arr) { return arr.map(function (p) { return [PXu(p.x), PYv(p.y)]; }); }
    scrCurves.melt = toScr(meltPts); scrCurves.vap = toScr(vapPts); scrCurves.sub = toScr(subPts);

    ctx.save();
    ctx.font = fs + 'px sans-serif';
    ctx.lineWidth = lw; ctx.strokeStyle = '#000'; ctx.fillStyle = '#000';

    /* axes with arrowheads */
    seg(ctx, a.left, a.bottom, a.left, a.top - ext + ah);
    head(ctx, a.left, a.top - ext, -Math.PI / 2, ah);
    seg(ctx, a.left, a.bottom, a.right + ext - ah, a.bottom);
    head(ctx, a.right + ext, a.bottom, 0, ah);

    /* ticks */
    var yT = [[218, '218'], [1, '1'], [0.006, '0.006']], maxLW = 0;
    for (i = 0; i < yT.length; i++) maxLW = Math.max(maxLW, ctx.measureText(yT[i][1]).width);
    for (i = 0; i < yT.length; i++) {
      var yy = PYv(vP(yT[i][0]));
      ctx.strokeStyle = '#000'; seg(ctx, a.left - tk, yy, a.left, yy);
      txt(ctx, yT[i][1], a.left - tk - 3, yy, { align: 'right', baseline: 'middle', font: fs + 'px sans-serif' });
    }
    var xT = [[0, '0'], [0.01, '0.01'], [100, '100'], [374, '374']];
    for (i = 0; i < xT.length; i++) {
      var xx = PXu(uT(xT[i][0]));
      ctx.strokeStyle = '#000'; seg(ctx, xx, a.bottom, xx, a.bottom + tk);
      txt(ctx, xT[i][1], xx, a.bottom + tk + 2, { align: 'center', baseline: 'top', font: fs + 'px sans-serif' });
    }

    /* axis titles + figure title */
    var xTit = Math.max(fs * 0.9, a.left - maxLW - tk - fs * 1.35);
    ctx.save();
    ctx.translate(xTit, (a.top + a.bottom) / 2); ctx.rotate(-Math.PI / 2);
    txt(ctx, 'Pressure, p (atm)', 0, 0, { align: 'center', baseline: 'middle', font: 'bold ' + fs + 'px sans-serif' });
    ctx.restore();
    txt(ctx, 'Temperature, T (°C)', (a.left + a.right) / 2, Math.min(chart.height - 3, a.bottom + tk + fs * 2.6),
      { align: 'center', baseline: 'alphabetic', font: 'bold ' + fs + 'px sans-serif' });
    txt(ctx, 'H₂O', (a.left + a.right) / 2, Math.max(fs * 1.3, a.top * 0.62),
      { align: 'center', baseline: 'alphabetic', font: 'bold ' + (fs * 1.25) + 'px sans-serif' });

    /* italic region letters */
    var rf = 'italic ' + (fs * 1.3) + 'px Georgia, serif';
    txt(ctx, 's', PXu(0.098), PYv(0.408), { align: 'center', baseline: 'middle', font: rf });
    txt(ctx, 'l', PXu(0.400), PYv(0.700), { align: 'center', baseline: 'middle', font: rf });
    txt(ctx, 'v', PXu(0.723), PYv(0.364), { align: 'center', baseline: 'middle', font: rf });

    /* special points */
    var rdot = cl(S * 0.0115, 3, 6);
    var xt = PXu(uTP), yt = PYv(vTP), xc = PXu(uCP), yc = PYv(vCP);
    ctx.fillStyle = '#000';
    ctx.beginPath(); ctx.arc(xt, yt, rdot, 0, 6.2832); ctx.fill();
    ctx.beginPath(); ctx.arc(xc, yc, rdot, 0, 6.2832); ctx.fill();
    txt(ctx, 'Triple', xt + rdot + 4, yt + fs * 1.05, { font: fs + 'px sans-serif' });
    txt(ctx, 'point', xt + rdot + 4, yt + fs * 2.15, { font: fs + 'px sans-serif' });
    ctx.font = fs + 'px sans-serif';
    var cpw = ctx.measureText('Critical point').width;
    var cpx = cl(xc - cpw * 0.62, 3, chart.width - cpw - 3);
    txt(ctx, 'Critical point', cpx, yc - rdot - fs * 0.75, { font: fs + 'px sans-serif' });

    /* outside annotations with curved leader arrows */
    var af = fs * 0.95;
    ctx.font = af + 'px sans-serif';
    while (af > 7 && ctx.measureText('Sublimation').width > a.left - 6) { af -= 0.5; ctx.font = af + 'px sans-serif'; }
    var annF = af + 'px sans-serif';
    ctx.lineWidth = cl(S * 0.0022, 0.9, 1.6); ctx.strokeStyle = '#000'; ctx.fillStyle = '#000';
    var hs = cl(S * 0.016, 4, 8);

    var mTx = PXu(uMeltU(0.755)), mTy = PYv(0.755);
    var mtw = ctx.measureText('Melting').width;
    var mx = Math.max(mtw + 3, a.left - maxLW - tk - 8);
    txt(ctx, 'Melting', mx, PYv(0.845), { align: 'right', baseline: 'middle', font: annF });
    curveArrow(ctx, mx + 5, PYv(0.845), (mx + mTx) / 2, PYv(0.818), mTx - 7, mTy, hs);

    var stw = ctx.measureText('Sublimation').width;
    var sx = Math.max(stw + 3, a.left - 6);
    txt(ctx, 'Sublimation', sx, PYv(0.152), { align: 'right', baseline: 'middle', font: annF });
    var sTx = PXu(uSubU(0.122)), sTy = PYv(0.122);
    curveArrow(ctx, sx + 5, PYv(0.152), (sx + sTx) / 2 + 6, PYv(0.135), sTx - 5, sTy + 3, hs);

    var btw = ctx.measureText('Boiling').width;
    var bx = Math.min(a.right + 8, chart.width - btw - 3);
    txt(ctx, 'Boiling', bx, PYv(0.545), { align: 'left', baseline: 'middle', font: annF });
    var bTx = PXu(VAP.inv(0.620)), bTy = PYv(0.620);
    curveArrow(ctx, bx - 4, PYv(0.545), (bx + bTx) / 2, PYv(0.548), bTx + 7, bTy, hs);

    /* heating-path boundary crossings */
    if (state.path) {
      var yp = PYv(vP(state.path)), cs = crossings(state.path);
      for (i = 0; i < cs.length; i++) {
        var cxp = PXu(cs[i].u);
        if (cxp < a.left || cxp > a.right) continue;
        ctx.strokeStyle = '#333'; ctx.lineWidth = cl(S * 0.0026, 1, 2);
        seg(ctx, cxp, yp - hs, cxp, yp + hs);
        var done = uT(state.T) >= cs[i].u;
        txt(ctx, cs[i].label, cxp, yp - hs - 3, {
          align: 'center', baseline: 'alphabetic',
          font: (done ? 'bold ' : '') + (fs * 0.82) + 'px sans-serif', color: done ? '#b0300a' : '#444'
        });
      }
      if (state.path > PC) {
        txt(ctx, 'no boundary crossed', PXu(0.62), yp + hs + fs * 1.05,
          { align: 'center', baseline: 'alphabetic', font: (fs * 0.82) + 'px sans-serif', color: '#7038b0' });
      }
    }

    /* movable state marker — ghosted until the student interacts */
    var ph2 = phaseOf(state.T, state.p);
    var mxp = PXu(cl(uT(state.T), 0, 1)), myp = PYv(cl(vP(state.p), 0, 1));
    var rm = cl(S * 0.016, 4, 8.5);
    ctx.save();
    ctx.globalAlpha = touched ? 1 : 0.22;
    ctx.lineWidth = cl(S * 0.0045, 1.5, 3);
    ctx.fillStyle = '#fff'; ctx.strokeStyle = '#111';
    ctx.beginPath(); ctx.arc(mxp, myp, rm, 0, 6.2832); ctx.fill(); ctx.stroke();
    ctx.fillStyle = PHASE[ph2].c;
    ctx.beginPath(); ctx.arc(mxp, myp, rm * 0.36, 0, 6.2832); ctx.fill();
    ctx.restore();

    ctx.restore();
  }
};

var layoutPlugin = {
  id: 'padw',
  beforeLayout: function (chart) {
    var w = chart.width, h = chart.height, S = Math.min(w, h);
    chart.options.layout.padding = {
      left: cl(w * 0.20, 54, 130), right: cl(w * 0.15, 46, 105),
      top: cl(h * 0.14, 34, 74), bottom: cl(h * 0.15, 38, 76)
    };
    var bw = cl(S * 0.0048, 1.4, 2.6);
    chart.data.datasets.forEach(function (d) { d.borderWidth = bw; });
  }
};

