/* ================= formatting / setters ================= */
function fmtT(T) {
  if (Math.abs(T) < 0.1) return T.toFixed(3);
  if (Math.abs(T) < 10) return T.toFixed(1);
  return T.toFixed(0);
}
function fmtP(p) {
  if (p < 0.01) return p.toFixed(4);
  if (p < 1) return p.toFixed(3);
  if (p < 10) return p.toFixed(2);
  return p.toFixed(0);
}
function setT(T) {
  T = cl(T, -20, 500);
  state.T = T;
  document.getElementById('temperatureInput').value = uT(T).toFixed(4);
  document.getElementById('temperatureVal').value = fmtT(T);
}
function setP(p) {
  p = cl(p, 0.001, 300);
  state.p = p;
  document.getElementById('pressureInput').value = String(cl(L10(p), -3, 2.477));
  document.getElementById('pressureVal').value = fmtP(p);
}
function redraw() {
  var ph = phaseOf(state.T, state.p);
  document.getElementById('stateReadout').textContent =
    'T = ' + fmtT(state.T) + ' °C   p = ' + fmtP(state.p) + ' atm';
  var el = document.getElementById('phaseReadout');
  el.textContent = PHASE[ph].name;
  el.style.color = PHASE[ph].c;
  chart.update('none');
}
function stopAnim() { if (anim) { cancelAnimationFrame(anim); anim = null; } }

/* ================= controls ================= */
function update_temperature(u) {
  stopAnim(); touched = true;
  var T = cl(Tu(u), -20, 500);
  state.T = T;
  document.getElementById('temperatureVal').value = fmtT(T);
  redraw();
}
function update_pressure(lg) {
  stopAnim(); touched = true;
  var p = cl(Math.pow(10, lg), 0.001, 300);
  state.p = p;
  document.getElementById('pressureVal').value = fmtP(p);
  redraw();
}
function applyPath(name) {
  state.path = PATHS[name] || null;
  var pi = document.getElementById('pressureInput');
  if (state.path) { setP(state.path); pi.disabled = true; } else { pi.disabled = false; }
}
function toggle_heatingPath(v) { stopAnim(); touched = true; applyPath(v); redraw(); }
function pathEndU() {
  var p = state.p;
  if (p > PC) return 0.90;
  if (p < PT) return 0.64;
  return Math.min(0.90, VAP.inv(vP(p)) + 0.105);
}
function animateU(uTarget, dur) {
  stopAnim(); touched = true;
  var u0 = uT(state.T), t0 = performance.now(); dur = dur || 3400;
  function frame(now) {
    var k = cl((now - t0) / dur, 0, 1);
    setT(Tu(u0 + (uTarget - u0) * k));
    redraw();
    anim = (k < 1) ? requestAnimationFrame(frame) : null;
  }
  anim = requestAnimationFrame(frame);
}
function animateP(pTarget, dur) {
  stopAnim(); touched = true;
  var v0 = vP(state.p), v1 = vP(pTarget), t0 = performance.now(); dur = dur || 2800;
  function frame(now) {
    var k = cl((now - t0) / dur, 0, 1);
    setP(Pv(v0 + (v1 - v0) * k));
    redraw();
    anim = (k < 1) ? requestAnimationFrame(frame) : null;
  }
  anim = requestAnimationFrame(frame);
}
function trigger_tracePath() {
  stopAnim(); touched = true;
  var end = pathEndU();
  setT(Tu(0.05)); redraw();
  animateU(end);
}

/* ================= demo steps ================= */
var U_SQUEEZE = 0.221;   /* inside the solid sliver, left of the triple point */
var STEPS = [
  {
    title: 'Read the map',
    narration: 'Three red curves carve the plane into solid (s), liquid (l) and vapor (v). At room conditions, 25 °C and 1 atm, the state point (faint circle) sits inside the liquid wedge — water is liquid there for no other reason than its location on this map.',
    state: { temperature: 25, pressure: 1, heatingPath: 'Free explore' }
  },
  {
    title: 'Cross the boiling curve',
    narration: 'Slide the temperature right at 1 atm. At 100 °C the point crosses the vaporization curve and the tinted region flips from liquid to vapor — that crossing is boiling.',
    state: { temperature: 130, pressure: 1, heatingPath: 'Free explore' }
  },
  {
    title: 'The triple point',
    narration: 'Drop the pressure to 0.006 atm and the temperature to 0.01 °C. All three curves meet at this single dot, the one condition where ice, water and steam coexist.',
    state: { temperature: 0.01, pressure: 0.006, heatingPath: 'Free explore' }
  },
  {
    title: 'Squeeze ice into water',
    narration: 'Park the point just inside the solid sliver at 1 atm (the T axis is stretched near 0 °C so the fusion curve\u2019s small LEFT lean is readable). Now watch the pressure climb: near 50 atm the point crosses the melting curve and ice becomes liquid — pressure alone melted it, possible only because that curve leans left.',
    state: { temperature: null, pressure: 200, heatingPath: 'Free explore', squeeze: true }
  },
  {
    title: 'Sublimation path',
    narration: 'Choose the low-pressure path, below the triple-point pressure, and heat. The point crosses only the sublimation curve: ice turns straight into vapor with no liquid stage.',
    state: { heatingPath: 'Low-pressure path (0.003 atm)', pressure: 0.003, temperature: 20 }
  },
  {
    title: 'Past the critical point',
    narration: 'Now take the supercritical path above 218 atm and heat past 374 °C. No boundary is crossed — liquid and vapor merge continuously into one indistinguishable supercritical fluid.',
    state: { heatingPath: 'Supercritical path (250 atm)', pressure: 250, temperature: 450 }
  }
];
var curStep = 0;
function applyStep(i) {
  stopAnim();
  curStep = (i + STEPS.length) % STEPS.length;
  var s = STEPS[curStep], st = s.state;
  touched = (curStep !== 0);
  if (st.heatingPath !== undefined) {
    document.getElementById('heatingPathInput').value = st.heatingPath;
    applyPath(st.heatingPath);
  }
  if (st.squeeze) {
    setT(Tu(U_SQUEEZE)); setP(1);
  } else {
    if (st.pressure !== undefined) setP(st.pressure);
    if (st.temperature !== null && st.temperature !== undefined) setT(st.temperature);
  }
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + STEPS.length + ' · ' + s.title;
  redraw();
  if (st.squeeze) {
    setTimeout(function () { if (curStep === 3) animateP(st.pressure); }, 400);
  } else if (st.heatingPath && st.heatingPath !== 'Free explore') {
    setT(Tu(0.05)); redraw();
    setTimeout(function () { if (curStep === i % STEPS.length || true) animateU(uT(st.temperature)); }, 350);
  }
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

/* ================= hover / click / drag ================= */
function dist2seg(px, py, x1, y1, x2, y2) {
  var dx = x2 - x1, dy = y2 - y1, L = dx * dx + dy * dy;
  var t = L ? cl(((px - x1) * dx + (py - y1) * dy) / L, 0, 1) : 0;
  var ax = x1 + t * dx - px, ay = y1 + t * dy - py;
  return Math.sqrt(ax * ax + ay * ay);
}
function nearCurve(pts, x, y) {
  var m = 1e9;
  for (var i = 1; i < pts.length; i++) m = Math.min(m, dist2seg(x, y, pts[i - 1][0], pts[i - 1][1], pts[i][0], pts[i][1]));
  return m;
}
function inArea(x, y) { return gArea && x >= gArea.left && x <= gArea.right && y >= gArea.top && y <= gArea.bottom; }
function hitTest(x, y) {
  if (!gArea) return null;
  var r = cl(gS * 0.03, 8, 14);
  var xt = PXu(uTP), yt = PYv(vTP), xc = PXu(uCP), yc = PYv(vCP);
  if (Math.hypot(x - xt, y - yt) < r) return {
    tip: 'Triple point — 0.01 °C, 0.006 atm', title: 'Triple point',
    popup: 'At 0.01 °C and 0.006 atm the melting, boiling and sublimation curves all meet. This is the only pressure–temperature combination where ice, liquid water and water vapor coexist in equilibrium.'
  };
  if (Math.hypot(x - xc, y - yc) < r) return {
    tip: 'Critical point — 374 °C, 218 atm', title: 'Critical point',
    popup: 'The vaporization curve ends here at 374 °C and 218 atm. Above the critical point the liquid and vapor densities become equal, so there is no boundary left to cross: the substance is a single supercritical fluid.'
  };
  var th = cl(gS * 0.018, 5, 9);
  if (nearCurve(scrCurves.melt, x, y) < th) return {
    tip: 'Fusion (melting) curve — solid ⇄ liquid', title: 'Melting (fusion) curve',
    popup: 'This nearly vertical boundary separates ice from liquid water. For water it leans slightly to the LEFT (negative slope) because ice is less dense than the liquid, so compressing ice at fixed temperature can push the state point across the curve and melt it.'
  };
  if (nearCurve(scrCurves.vap, x, y) < th) return {
    tip: 'Vaporization (boiling) curve — liquid ⇄ vapor', title: 'Vaporization curve',
    popup: 'Along this curve liquid and vapor coexist; it gives the boiling temperature at each pressure (100 °C at 1 atm). It starts at the triple point and rises ever more steeply to the critical point, where the distinction between liquid and vapor disappears.'
  };
  if (nearCurve(scrCurves.sub, x, y) < th) return {
    tip: 'Sublimation curve — solid ⇄ vapor', title: 'Sublimation curve',
    popup: 'Below the triple-point pressure of 0.006 atm no liquid can exist. Heating ice at such low pressure carries the state point across this curve, and the solid passes directly into vapor — sublimation.'
  };
  return null;
}
